-- =============================================================================
-- Indent Easy — Initial PostgreSQL schema (baseline migration 0001)
-- Target: PostgreSQL 16+ . Validated by applying to a clean PostgreSQL 16 instance.
-- IDs: UUIDv7 generated by the application; gen_random_uuid() default is a fallback.
-- Money numeric(18,2) INR; quantities numeric(18,3) in product base UOM.
-- Every business table carries organization_id (multi-org ready; RLS enabled at the end).
-- =============================================================================

CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE SCHEMA IF NOT EXISTS org;
CREATE SCHEMA IF NOT EXISTS identity;
CREATE SCHEMA IF NOT EXISTS config;
CREATE SCHEMA IF NOT EXISTS catalog;
CREATE SCHEMA IF NOT EXISTS indent;
CREATE SCHEMA IF NOT EXISTS workflow;
CREATE SCHEMA IF NOT EXISTS procurement;
CREATE SCHEMA IF NOT EXISTS receiving;
CREATE SCHEMA IF NOT EXISTS logistics;
CREATE SCHEMA IF NOT EXISTS inventory;
CREATE SCHEMA IF NOT EXISTS mpp;
CREATE SCHEMA IF NOT EXISTS recon;
CREATE SCHEMA IF NOT EXISTS finance;
CREATE SCHEMA IF NOT EXISTS docs;
CREATE SCHEMA IF NOT EXISTS notify;
CREATE SCHEMA IF NOT EXISTS audit;
CREATE SCHEMA IF NOT EXISTS events;
CREATE SCHEMA IF NOT EXISTS io;
CREATE SCHEMA IF NOT EXISTS reporting;

-- -----------------------------------------------------------------------------
-- Shared helpers
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.forbid_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'Table %.% is append-only (% not allowed)', TG_TABLE_SCHEMA, TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'insufficient_privilege';
END $$;

CREATE OR REPLACE FUNCTION public.touch_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END $$;

-- =============================================================================
-- ORG
-- =============================================================================
CREATE TABLE org.organization (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name            text NOT NULL,
  legal_name      text,
  gstin           text,
  base_currency   char(3) NOT NULL DEFAULT 'INR',
  time_zone       text NOT NULL DEFAULT 'Asia/Kolkata',
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz
);

CREATE TABLE org.region (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  code            text NOT NULL,
  name            text NOT NULL,
  CONSTRAINT uq_region_code UNIQUE (organization_id, code)
);

CREATE TABLE org.location (
  id                          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id             uuid NOT NULL REFERENCES org.organization(id),
  region_id                   uuid REFERENCES org.region(id),
  code                        text NOT NULL,
  name                        text NOT NULL,
  name_hi                     text,
  type                        text NOT NULL,
  sap_plant_code              text,
  address                     text,
  gstin                       text,
  excluded_from_cross_view    boolean NOT NULL DEFAULT false,
  status                      text NOT NULL DEFAULT 'ACTIVE',
  legacy_name                 text,
  created_at                  timestamptz NOT NULL DEFAULT now(),
  updated_at                  timestamptz,
  version                     integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_location_code UNIQUE (organization_id, code),
  CONSTRAINT ck_location_type CHECK (type IN ('HEAD_OFFICE','BMC','MCC','PLANT','WAREHOUSE','OTHER')),
  CONSTRAINT ck_location_status CHECK (status IN ('ACTIVE','INACTIVE'))
);
CREATE UNIQUE INDEX uq_location_sap_plant ON org.location (organization_id, sap_plant_code) WHERE sap_plant_code IS NOT NULL;

CREATE TABLE org.warehouse (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  location_id     uuid REFERENCES org.location(id),
  code            text NOT NULL,
  name            text NOT NULL,
  type            text NOT NULL DEFAULT 'STORE',
  status          text NOT NULL DEFAULT 'ACTIVE',
  created_at      timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_warehouse_code UNIQUE (organization_id, code),
  CONSTRAINT ck_warehouse_type CHECK (type IN ('STORE','IN_TRANSIT','QUARANTINE','DAMAGED','EXPIRED')),
  CONSTRAINT ck_warehouse_location CHECK (type = 'IN_TRANSIT' OR location_id IS NOT NULL)
);
CREATE UNIQUE INDEX uq_warehouse_single_transit ON org.warehouse (organization_id) WHERE type = 'IN_TRANSIT';
CREATE INDEX ix_warehouse_location ON org.warehouse (location_id);

CREATE TABLE org.department (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  code            text NOT NULL,
  name            text NOT NULL,
  status          text NOT NULL DEFAULT 'ACTIVE',
  CONSTRAINT uq_department_code UNIQUE (organization_id, code)
);

CREATE TABLE org.designation (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  code            text NOT NULL,
  name            text NOT NULL,
  CONSTRAINT uq_designation_code UNIQUE (organization_id, code)
);

-- =============================================================================
-- IDENTITY
-- =============================================================================
CREATE TABLE identity.app_user (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id       uuid NOT NULL REFERENCES org.organization(id),
  email                 citext NOT NULL,
  mobile_e164           text,
  employee_code         text,
  display_name          text NOT NULL,
  department_id         uuid REFERENCES org.department(id),
  designation_id        uuid REFERENCES org.designation(id),
  primary_location_id   uuid REFERENCES org.location(id),
  delivery_point_code   text,
  preferred_locale      text NOT NULL DEFAULT 'EN',
  signature_document_id uuid,
  seal_document_id      uuid,
  reports_to_id         uuid REFERENCES identity.app_user(id),
  status                text NOT NULL DEFAULT 'INVITED',
  password_hash         text,
  password_changed_at   timestamptz,
  must_change_password  boolean NOT NULL DEFAULT false,
  failed_attempts       integer NOT NULL DEFAULT 0,
  locked_until          timestamptz,
  mfa_enforced          boolean NOT NULL DEFAULT false,
  roles_version         integer NOT NULL DEFAULT 1,
  last_login_at         timestamptz,
  legacy_user_id        bigint,
  created_at            timestamptz NOT NULL DEFAULT now(),
  created_by            uuid,
  updated_at            timestamptz,
  updated_by            uuid,
  version               integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_user_email UNIQUE (email),
  CONSTRAINT uq_user_employee_code UNIQUE (organization_id, employee_code),
  CONSTRAINT uq_user_delivery_point UNIQUE (organization_id, delivery_point_code),
  CONSTRAINT ck_user_status CHECK (status IN ('INVITED','ACTIVE','LOCKED','DISABLED')),
  CONSTRAINT ck_user_locale CHECK (preferred_locale IN ('EN','HI')),
  CONSTRAINT ck_user_mobile CHECK (mobile_e164 IS NULL OR mobile_e164 ~ '^\+[1-9][0-9]{7,14}$')
);
CREATE INDEX ix_user_location ON identity.app_user (primary_location_id);
CREATE INDEX ix_user_name_trgm ON identity.app_user USING gin (display_name gin_trgm_ops);

CREATE TABLE identity.user_location (
  user_id     uuid NOT NULL REFERENCES identity.app_user(id) ON DELETE CASCADE,
  location_id uuid NOT NULL REFERENCES org.location(id),
  PRIMARY KEY (user_id, location_id)
);

CREATE TABLE identity.permission (
  code        text PRIMARY KEY,
  description text NOT NULL,
  CONSTRAINT ck_permission_code CHECK (code ~ '^[a-z_]+:[a-z_]+$')
);

CREATE TABLE identity.role (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id     uuid NOT NULL REFERENCES org.organization(id),
  code                text NOT NULL,
  name                text NOT NULL,
  description         text,
  is_system           boolean NOT NULL DEFAULT false,
  home_workspace      text,
  home_priority       integer NOT NULL DEFAULT 100,
  status              text NOT NULL DEFAULT 'ACTIVE',
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz,
  version             integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_role_code UNIQUE (organization_id, code)
);

CREATE TABLE identity.role_permission (
  role_id         uuid NOT NULL REFERENCES identity.role(id) ON DELETE CASCADE,
  permission_code text NOT NULL REFERENCES identity.permission(code),
  PRIMARY KEY (role_id, permission_code)
);

CREATE TABLE identity.user_role (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id               uuid NOT NULL REFERENCES identity.app_user(id) ON DELETE CASCADE,
  role_id               uuid NOT NULL REFERENCES identity.role(id),
  scope_location_ids    uuid[] NOT NULL DEFAULT '{}',
  scope_department_ids  uuid[] NOT NULL DEFAULT '{}',
  scope_category_ids    uuid[] NOT NULL DEFAULT '{}',
  valid_from            date,
  valid_to              date,
  created_at            timestamptz NOT NULL DEFAULT now(),
  created_by            uuid,
  CONSTRAINT uq_user_role UNIQUE (user_id, role_id),
  CONSTRAINT ck_user_role_validity CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from)
);
CREATE INDEX ix_user_role_scope_loc ON identity.user_role USING gin (scope_location_ids);

CREATE TABLE identity.session (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id         uuid NOT NULL REFERENCES identity.app_user(id),
  device_name     text,
  platform        text,
  client_version  text,
  ip              inet,
  user_agent      text,
  created_at      timestamptz NOT NULL DEFAULT now(),
  last_seen_at    timestamptz NOT NULL DEFAULT now(),
  idle_expires_at timestamptz NOT NULL,
  absolute_expires_at timestamptz NOT NULL,
  revoked_at      timestamptz,
  revoke_reason   text
);
CREATE INDEX ix_session_user_active ON identity.session (user_id) WHERE revoked_at IS NULL;

CREATE TABLE identity.refresh_token (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id      uuid NOT NULL REFERENCES identity.session(id) ON DELETE CASCADE,
  family_id       uuid NOT NULL,
  token_hash      bytea NOT NULL,
  issued_at       timestamptz NOT NULL DEFAULT now(),
  expires_at      timestamptz NOT NULL,
  used_at         timestamptz,
  replaced_by_id  uuid REFERENCES identity.refresh_token(id),
  CONSTRAINT uq_refresh_token_hash UNIQUE (token_hash)
);
CREATE INDEX ix_refresh_family ON identity.refresh_token (family_id);

CREATE TABLE identity.password_reset_token (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     uuid NOT NULL REFERENCES identity.app_user(id),
  token_hash  bytea NOT NULL UNIQUE,
  expires_at  timestamptz NOT NULL,
  used_at     timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE identity.mfa_factor (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id           uuid NOT NULL REFERENCES identity.app_user(id),
  type              text NOT NULL,
  secret_encrypted  bytea,
  confirmed_at      timestamptz,
  created_at        timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ck_mfa_type CHECK (type IN ('TOTP','SMS_OTP','RECOVERY_CODES'))
);

CREATE TABLE identity.api_client (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  name            text NOT NULL,
  key_prefix      text NOT NULL UNIQUE,
  key_hash        bytea NOT NULL,
  scopes          text[] NOT NULL,
  status          text NOT NULL DEFAULT 'ACTIVE',
  last_used_at    timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE org.employee (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  employee_code   text NOT NULL,
  name            text NOT NULL,
  department_id   uuid REFERENCES org.department(id),
  user_id         uuid REFERENCES identity.app_user(id),
  status          text NOT NULL DEFAULT 'ACTIVE',
  CONSTRAINT uq_employee_code UNIQUE (organization_id, employee_code)
);

-- =============================================================================
-- CONFIG
-- =============================================================================
CREATE TABLE config.setting (
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  key             text NOT NULL,
  scope_type      text NOT NULL DEFAULT 'ORGANIZATION',
  scope_id        uuid NOT NULL DEFAULT '00000000-0000-0000-0000-000000000000',
  value           jsonb NOT NULL,
  value_schema    jsonb,
  description     text,
  updated_at      timestamptz NOT NULL DEFAULT now(),
  updated_by      uuid,
  PRIMARY KEY (organization_id, key, scope_type, scope_id),
  CONSTRAINT ck_setting_scope CHECK (scope_type IN ('ORGANIZATION','LOCATION'))
);

CREATE TABLE config.number_series (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  doc_type        text NOT NULL,
  location_id     uuid REFERENCES org.location(id),
  fiscal_year     text,
  prefix          text NOT NULL,
  padding         integer NOT NULL DEFAULT 4,
  next_value      bigint NOT NULL DEFAULT 1,
  reset_policy    text NOT NULL DEFAULT 'NEVER',
  updated_at      timestamptz,
  CONSTRAINT ck_series_padding CHECK (padding BETWEEN 1 AND 12),
  CONSTRAINT ck_series_next CHECK (next_value >= 1),
  CONSTRAINT ck_series_reset CHECK (reset_policy IN ('NEVER','FISCAL_YEAR','CALENDAR_YEAR'))
);
CREATE UNIQUE INDEX uq_number_series ON config.number_series
  (organization_id, doc_type, coalesce(location_id, '00000000-0000-0000-0000-000000000000'::uuid), coalesce(fiscal_year, ''));

-- Allocate next number atomically (row lock serialises concurrent callers).
CREATE OR REPLACE FUNCTION config.next_document_number(p_org uuid, p_doc_type text, p_location uuid DEFAULT NULL, p_fy text DEFAULT NULL)
RETURNS text LANGUAGE plpgsql AS $$
DECLARE r config.number_series%ROWTYPE;
BEGIN
  SELECT * INTO r FROM config.number_series
   WHERE organization_id = p_org AND doc_type = p_doc_type
     AND location_id IS NOT DISTINCT FROM p_location
     AND fiscal_year IS NOT DISTINCT FROM p_fy
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Number series % not configured', p_doc_type USING ERRCODE = 'no_data_found';
  END IF;
  UPDATE config.number_series SET next_value = next_value + 1, updated_at = now() WHERE id = r.id;
  RETURN r.prefix || lpad(r.next_value::text, r.padding, '0');
END $$;

CREATE TABLE config.feature_flag (
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  key             text NOT NULL,
  enabled         boolean NOT NULL DEFAULT false,
  rules           jsonb,
  description     text,
  updated_at      timestamptz NOT NULL DEFAULT now(),
  updated_by      uuid,
  PRIMARY KEY (organization_id, key)
);

CREATE TABLE config.holiday (
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  location_id     uuid REFERENCES org.location(id),
  holiday_date    date NOT NULL,
  name            text NOT NULL
);
CREATE UNIQUE INDEX uq_holiday ON config.holiday (organization_id, coalesce(location_id, '00000000-0000-0000-0000-000000000000'::uuid), holiday_date);

-- =============================================================================
-- CATALOG
-- =============================================================================
CREATE TABLE catalog.uom (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id   uuid NOT NULL REFERENCES org.organization(id),
  code              text NOT NULL,
  name              text NOT NULL,
  name_hi           text,
  decimals_allowed  smallint NOT NULL DEFAULT 0,
  legacy_codes      text[] NOT NULL DEFAULT '{}',
  CONSTRAINT uq_uom_code UNIQUE (organization_id, code),
  CONSTRAINT ck_uom_decimals CHECK (decimals_allowed BETWEEN 0 AND 3)
);

CREATE TABLE catalog.product_category (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id     uuid NOT NULL REFERENCES org.organization(id),
  parent_id           uuid REFERENCES catalog.product_category(id),
  code                text NOT NULL,
  name                text NOT NULL,
  owner_user_id       uuid REFERENCES identity.app_user(id),
  requires_inspection boolean NOT NULL DEFAULT false,
  CONSTRAINT uq_category_code UNIQUE (organization_id, code)
);

CREATE TABLE catalog.product (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id   uuid NOT NULL REFERENCES org.organization(id),
  code              text NOT NULL,
  name              text NOT NULL,
  name_hi           text,
  size_label        text,
  base_uom_id       uuid NOT NULL REFERENCES catalog.uom(id),
  category_id       uuid REFERENCES catalog.product_category(id),
  material_type     text,
  hsn_code          text,
  standard_price    numeric(18,2) NOT NULL DEFAULT 0,
  is_stock_item     boolean NOT NULL DEFAULT true,
  is_service        boolean NOT NULL DEFAULT false,
  batch_tracked     boolean NOT NULL DEFAULT false,
  serial_tracked    boolean NOT NULL DEFAULT false,
  reorder_level     numeric(18,3),
  owner_user_id     uuid REFERENCES identity.app_user(id),
  status            text NOT NULL DEFAULT 'ACTIVE',
  legacy_product_id bigint,
  search_tsv        tsvector GENERATED ALWAYS AS (
                      to_tsvector('simple', coalesce(code,'') || ' ' || coalesce(name,'') || ' ' || coalesce(size_label,'') || ' ' || coalesce(material_type,''))
                    ) STORED,
  created_at        timestamptz NOT NULL DEFAULT now(),
  created_by        uuid,
  updated_at        timestamptz,
  updated_by        uuid,
  version           integer NOT NULL DEFAULT 1,
  deleted_at        timestamptz,
  CONSTRAINT uq_product_code UNIQUE (organization_id, code),
  CONSTRAINT ck_product_price CHECK (standard_price >= 0),
  CONSTRAINT ck_product_status CHECK (status IN ('ACTIVE','INACTIVE')),
  CONSTRAINT ck_product_service_stock CHECK (NOT (is_service AND is_stock_item))
);
CREATE UNIQUE INDEX uq_product_name_size ON catalog.product (organization_id, lower(name), coalesce(lower(size_label), ''));
CREATE INDEX ix_product_tsv ON catalog.product USING gin (search_tsv);
CREATE INDEX ix_product_name_trgm ON catalog.product USING gin (name gin_trgm_ops);
CREATE INDEX ix_product_owner ON catalog.product (owner_user_id);

CREATE TABLE catalog.uom_conversion (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  from_uom_id uuid NOT NULL REFERENCES catalog.uom(id),
  to_uom_id   uuid NOT NULL REFERENCES catalog.uom(id),
  product_id  uuid REFERENCES catalog.product(id),
  factor      numeric(18,6) NOT NULL,
  CONSTRAINT ck_uom_conv_factor CHECK (factor > 0),
  CONSTRAINT ck_uom_conv_distinct CHECK (from_uom_id <> to_uom_id)
);
CREATE UNIQUE INDEX uq_uom_conversion ON catalog.uom_conversion
  (from_uom_id, to_uom_id, coalesce(product_id, '00000000-0000-0000-0000-000000000000'::uuid));

CREATE TABLE catalog.external_system (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id   uuid NOT NULL REFERENCES org.organization(id),
  code              text NOT NULL,
  name              text NOT NULL,
  display_priority  integer NOT NULL DEFAULT 100,
  CONSTRAINT uq_external_system UNIQUE (organization_id, code)
);

CREATE TABLE catalog.product_external_code (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id     uuid NOT NULL REFERENCES org.organization(id),
  product_id          uuid NOT NULL REFERENCES catalog.product(id),
  external_system_id  uuid NOT NULL REFERENCES catalog.external_system(id),
  external_code       text,
  external_name       text NOT NULL,
  uom_text            text,
  is_primary          boolean NOT NULL DEFAULT true,
  status              text NOT NULL DEFAULT 'ACTIVE',
  legacy_group_name   text,
  created_at          timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX uq_ext_code ON catalog.product_external_code (organization_id, external_system_id, external_code) WHERE external_code IS NOT NULL AND status = 'ACTIVE';
CREATE UNIQUE INDEX uq_ext_primary ON catalog.product_external_code (product_id, external_system_id) WHERE is_primary AND status = 'ACTIVE';
CREATE INDEX ix_ext_name_trgm ON catalog.product_external_code USING gin (external_name gin_trgm_ops);

CREATE TABLE catalog.vendor (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id     uuid NOT NULL REFERENCES org.organization(id),
  code                text NOT NULL,
  name                text NOT NULL,
  legal_name          text,
  gstin               text,
  pan                 text,
  sap_vendor_code     text,
  payment_terms_days  integer,
  address             jsonb,
  status              text NOT NULL DEFAULT 'ACTIVE',
  legacy_vendor_ids   bigint[] NOT NULL DEFAULT '{}',
  search_tsv          tsvector GENERATED ALWAYS AS (to_tsvector('simple', coalesce(code,'') || ' ' || coalesce(name,'') || ' ' || coalesce(gstin,''))) STORED,
  created_at          timestamptz NOT NULL DEFAULT now(),
  created_by          uuid,
  updated_at          timestamptz,
  updated_by          uuid,
  version             integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_vendor_code UNIQUE (organization_id, code),
  CONSTRAINT ck_vendor_status CHECK (status IN ('ACTIVE','INACTIVE','BLOCKED')),
  CONSTRAINT ck_vendor_gstin CHECK (gstin IS NULL OR gstin ~ '^[0-9]{2}[A-Z0-9]{13}$')
);
CREATE UNIQUE INDEX uq_vendor_name ON catalog.vendor (organization_id, lower(name));
CREATE UNIQUE INDEX uq_vendor_gstin ON catalog.vendor (organization_id, gstin) WHERE gstin IS NOT NULL;
CREATE INDEX ix_vendor_tsv ON catalog.vendor USING gin (search_tsv);

CREATE TABLE catalog.vendor_contact (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  vendor_id   uuid NOT NULL REFERENCES catalog.vendor(id) ON DELETE CASCADE,
  name        text,
  email       citext,
  phone_e164  text,
  purposes    text[] NOT NULL DEFAULT '{PO}',
  status      text NOT NULL DEFAULT 'ACTIVE',
  CONSTRAINT ck_contact_channel CHECK (email IS NOT NULL OR phone_e164 IS NOT NULL)
);
CREATE INDEX ix_vendor_contact_vendor ON catalog.vendor_contact (vendor_id);

CREATE TABLE catalog.vendor_product (
  vendor_id       uuid NOT NULL REFERENCES catalog.vendor(id),
  product_id      uuid NOT NULL REFERENCES catalog.product(id),
  priority        integer NOT NULL DEFAULT 1,
  is_primary      boolean NOT NULL DEFAULT false,
  last_price      numeric(18,4),
  lead_time_days  integer,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (vendor_id, product_id)
);
CREATE INDEX ix_vendor_product_product ON catalog.vendor_product (product_id);

CREATE TABLE catalog.mpp (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id       uuid NOT NULL REFERENCES org.organization(id),
  code                  text NOT NULL,
  name                  text NOT NULL,
  bmc_location_id       uuid NOT NULL REFERENCES org.location(id),
  sahayak_name          text,
  sahayak_mobile_e164   text,
  cycle_band            text,
  village               text,
  status                text NOT NULL DEFAULT 'ACTIVE',
  legacy_mpp_id         bigint,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz,
  version               integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_mpp_code UNIQUE (organization_id, code),
  CONSTRAINT ck_mpp_status CHECK (status IN ('ACTIVE','INACTIVE')),
  CONSTRAINT ck_mpp_band CHECK (cycle_band IS NULL OR cycle_band IN ('DAYS_1_10','DAYS_11_20','DAYS_21_31')),
  CONSTRAINT ck_mpp_mobile CHECK (sahayak_mobile_e164 IS NULL OR sahayak_mobile_e164 ~ '^\+[1-9][0-9]{7,14}$')
);
CREATE INDEX ix_mpp_bmc ON catalog.mpp (bmc_location_id);
CREATE INDEX ix_mpp_name_trgm ON catalog.mpp USING gin (name gin_trgm_ops);

-- =============================================================================
-- INDENT
-- =============================================================================
CREATE TABLE indent.indent (
  id                          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id             uuid NOT NULL REFERENCES org.organization(id),
  indent_number               text,
  location_id                 uuid NOT NULL REFERENCES org.location(id),
  department_id               uuid REFERENCES org.department(id),
  requested_by_user_id        uuid NOT NULL REFERENCES identity.app_user(id),
  requested_for_employee_id   uuid REFERENCES org.employee(id),
  priority                    text NOT NULL DEFAULT 'NORMAL',
  required_by                 date,
  justification               text,
  budget_code                 text,
  remarks                     text,
  status                      text NOT NULL DEFAULT 'DRAFT',
  estimated_total             numeric(18,2) NOT NULL DEFAULT 0,
  submitted_at                timestamptz,
  workflow_instance_id        uuid,
  channel                     text NOT NULL DEFAULT 'WEB',
  client_ref                  uuid,
  legacy_requisition_number   text,
  search_tsv                  tsvector GENERATED ALWAYS AS (to_tsvector('simple', coalesce(indent_number,'') || ' ' || coalesce(justification,'') || ' ' || coalesce(remarks,''))) STORED,
  created_at                  timestamptz NOT NULL DEFAULT now(),
  created_by                  uuid,
  updated_at                  timestamptz,
  updated_by                  uuid,
  version                     integer NOT NULL DEFAULT 1,
  CONSTRAINT ck_indent_status CHECK (status IN ('DRAFT','PENDING_APPROVAL','PARTIALLY_APPROVED','RETURNED','APPROVED','REJECTED','IN_FULFILMENT','FULFILLED','CLOSED','CANCELLED')),
  CONSTRAINT ck_indent_priority CHECK (priority IN ('LOW','NORMAL','HIGH','URGENT')),
  CONSTRAINT ck_indent_number_after_submit CHECK (status = 'DRAFT' OR indent_number IS NOT NULL),
  CONSTRAINT ck_indent_total CHECK (estimated_total >= 0)
);
CREATE UNIQUE INDEX uq_indent_number ON indent.indent (organization_id, indent_number) WHERE indent_number IS NOT NULL;
CREATE UNIQUE INDEX uq_indent_client_ref ON indent.indent (organization_id, requested_by_user_id, client_ref) WHERE client_ref IS NOT NULL;
CREATE INDEX ix_indent_location_status ON indent.indent (location_id, status, submitted_at DESC);
CREATE INDEX ix_indent_requester ON indent.indent (requested_by_user_id, created_at DESC);
CREATE INDEX ix_indent_tsv ON indent.indent USING gin (search_tsv);

CREATE TABLE indent.indent_line (
  id                      uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id         uuid NOT NULL REFERENCES org.organization(id),
  indent_id               uuid NOT NULL REFERENCES indent.indent(id) ON DELETE CASCADE,
  line_no                 integer NOT NULL,
  product_id              uuid NOT NULL REFERENCES catalog.product(id),
  product_snapshot        jsonb NOT NULL,
  qty_requested           numeric(18,3) NOT NULL,
  uom_id                  uuid NOT NULL REFERENCES catalog.uom(id),
  qty_base                numeric(18,3) NOT NULL,
  expected_delivery_date  date,
  est_unit_price          numeric(18,4),
  est_amount              numeric(18,2),
  remark                  text,
  remark_internal         boolean NOT NULL DEFAULT false,
  status                  text NOT NULL DEFAULT 'DRAFT',
  qty_approved            numeric(18,3) NOT NULL DEFAULT 0,
  qty_rejected            numeric(18,3) NOT NULL DEFAULT 0,
  qty_ordered             numeric(18,3) NOT NULL DEFAULT 0,
  qty_transferred         numeric(18,3) NOT NULL DEFAULT 0,
  qty_received            numeric(18,3) NOT NULL DEFAULT 0,
  approval_group_key      text,
  client_line_id          uuid,
  legacy_requisition_id   bigint,
  version                 integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_indent_line_no UNIQUE (indent_id, line_no),
  CONSTRAINT ck_indent_line_qty CHECK (qty_requested > 0 AND qty_base > 0),
  CONSTRAINT ck_indent_line_approved CHECK (qty_approved >= 0 AND qty_approved + qty_rejected <= qty_base),
  CONSTRAINT ck_indent_line_fulfil CHECK (qty_ordered + qty_transferred <= qty_approved),
  CONSTRAINT ck_indent_line_status CHECK (status IN ('DRAFT','PENDING_APPROVAL','RETURNED','APPROVED','APPROVED_FOR_TRANSFER','REJECTED','PO_CREATED','STN_ISSUED','PARTIALLY_RECEIVED','RECEIVED','CLOSED_SHORT','CANCELLED'))
);
CREATE INDEX ix_indent_line_product_status ON indent.indent_line (product_id, status);
CREATE INDEX ix_indent_line_procurement ON indent.indent_line (status) WHERE status = 'APPROVED';

-- =============================================================================
-- WORKFLOW
-- =============================================================================
CREATE TABLE workflow.workflow_definition (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  code            text NOT NULL,
  name            text NOT NULL,
  subject_type    text NOT NULL,
  CONSTRAINT uq_wf_def UNIQUE (organization_id, code),
  CONSTRAINT ck_wf_subject CHECK (subject_type IN ('INDENT','PURCHASE_ORDER','GRN_EXCESS','GRN_REVERSAL','STOCK_ADJUSTMENT','TRANSFER_REQUEST','ADVANCE_SALE_CANCELLATION','INVOICE_EXCEPTION','TRANSIT_WRITE_OFF'))
);

CREATE TABLE workflow.workflow_version (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  definition_id   uuid NOT NULL REFERENCES workflow.workflow_definition(id),
  version_no      integer NOT NULL,
  definition      jsonb NOT NULL,
  status          text NOT NULL DEFAULT 'DRAFT',
  published_at    timestamptz,
  published_by    uuid REFERENCES identity.app_user(id),
  created_at      timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_wf_version UNIQUE (definition_id, version_no),
  CONSTRAINT ck_wf_version_status CHECK (status IN ('DRAFT','PUBLISHED','RETIRED'))
);
CREATE UNIQUE INDEX uq_wf_single_published ON workflow.workflow_version (definition_id) WHERE status = 'PUBLISHED';

CREATE TABLE workflow.workflow_instance (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  version_id      uuid NOT NULL REFERENCES workflow.workflow_version(id),
  subject_type    text NOT NULL,
  subject_id      uuid NOT NULL,
  status          text NOT NULL DEFAULT 'RUNNING',
  context         jsonb NOT NULL DEFAULT '{}',
  previous_instance_id uuid REFERENCES workflow.workflow_instance(id),
  started_at      timestamptz NOT NULL DEFAULT now(),
  completed_at    timestamptz,
  CONSTRAINT ck_wf_instance_status CHECK (status IN ('RUNNING','COMPLETED','RETURNED','CANCELLED'))
);
CREATE INDEX ix_wf_instance_subject ON workflow.workflow_instance (subject_type, subject_id);

CREATE TABLE workflow.approval_group (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  instance_id   uuid NOT NULL REFERENCES workflow.workflow_instance(id),
  routing_key   text NOT NULL,
  line_ids      uuid[] NOT NULL DEFAULT '{}',
  current_step  text,
  outcome       text,
  decided_at    timestamptz,
  CONSTRAINT ck_group_outcome CHECK (outcome IS NULL OR outcome IN ('APPROVED','APPROVED_FOR_TRANSFER','REJECTED','RETURNED','CANCELLED','MIXED'))
);
CREATE INDEX ix_approval_group_instance ON workflow.approval_group (instance_id);

CREATE TABLE workflow.approval_task (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id       uuid NOT NULL REFERENCES org.organization(id),
  instance_id           uuid NOT NULL REFERENCES workflow.workflow_instance(id),
  group_id              uuid REFERENCES workflow.approval_group(id),
  step_key              text NOT NULL,
  step_name             text NOT NULL,
  subject_type          text NOT NULL,
  subject_id            uuid NOT NULL,
  subject_number        text,
  amount                numeric(18,2),
  assignee_user_id      uuid REFERENCES identity.app_user(id),
  assignee_role_id      uuid REFERENCES identity.role(id),
  on_behalf_of_user_id  uuid REFERENCES identity.app_user(id),
  mode                  text NOT NULL DEFAULT 'ANY',
  status                text NOT NULL DEFAULT 'PENDING',
  due_at                timestamptz,
  reminded_at           timestamptz,
  escalated_at          timestamptz,
  acted_at              timestamptz,
  acted_by              uuid REFERENCES identity.app_user(id),
  action                text,
  remark                text,
  created_at            timestamptz NOT NULL DEFAULT now(),
  version               integer NOT NULL DEFAULT 1,
  CONSTRAINT ck_task_assignee CHECK (assignee_user_id IS NOT NULL OR assignee_role_id IS NOT NULL),
  CONSTRAINT ck_task_mode CHECK (mode IN ('ANY','ALL','QUORUM')),
  CONSTRAINT ck_task_status CHECK (status IN ('PENDING','ESCALATED','APPROVED','REJECTED','RETURNED','CANCELLED','REASSIGNED')),
  CONSTRAINT ck_task_acted CHECK ((status IN ('PENDING','ESCALATED')) = (acted_at IS NULL) OR status IN ('CANCELLED','REASSIGNED'))
);
CREATE INDEX ix_task_assignee_open ON workflow.approval_task (assignee_user_id, created_at) WHERE status IN ('PENDING','ESCALATED');
CREATE INDEX ix_task_role_open ON workflow.approval_task (assignee_role_id) WHERE status IN ('PENDING','ESCALATED');
CREATE INDEX ix_task_due ON workflow.approval_task (due_at) WHERE status IN ('PENDING','ESCALATED');
CREATE INDEX ix_task_subject ON workflow.approval_task (subject_type, subject_id);

CREATE TABLE workflow.approval_action (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  task_id         uuid NOT NULL REFERENCES workflow.approval_task(id),
  action          text NOT NULL,
  actor_id        uuid NOT NULL REFERENCES identity.app_user(id),
  on_behalf_of_id uuid REFERENCES identity.app_user(id),
  remark          text,
  payload         jsonb,
  ip              inet,
  user_agent      text,
  occurred_at     timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ck_action_type CHECK (action IN ('APPROVE','APPROVE_FOR_TRANSFER','REJECT','RETURN','DELEGATE','REASSIGN','ESCALATE','REMIND','COMMENT'))
);
CREATE INDEX ix_action_task ON workflow.approval_action (task_id);
CREATE TRIGGER tg_approval_action_append_only BEFORE UPDATE OR DELETE ON workflow.approval_action
  FOR EACH ROW EXECUTE FUNCTION public.forbid_mutation();

CREATE TABLE workflow.delegation (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id   uuid NOT NULL REFERENCES org.organization(id),
  delegator_id      uuid NOT NULL REFERENCES identity.app_user(id),
  delegate_id       uuid NOT NULL REFERENCES identity.app_user(id),
  definition_codes  text[] NOT NULL,
  scope             jsonb,
  max_amount        numeric(18,2),
  valid_from        timestamptz NOT NULL,
  valid_to          timestamptz NOT NULL,
  reason            text,
  status            text NOT NULL DEFAULT 'ACTIVE',
  created_at        timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ck_delegation_period CHECK (valid_to > valid_from),
  CONSTRAINT ck_delegation_self CHECK (delegator_id <> delegate_id),
  CONSTRAINT ck_delegation_status CHECK (status IN ('ACTIVE','REVOKED','EXPIRED'))
);
CREATE INDEX ix_delegation_active ON workflow.delegation (delegator_id, valid_from, valid_to) WHERE status = 'ACTIVE';

-- =============================================================================
-- PROCUREMENT
-- =============================================================================
CREATE TABLE procurement.purchase_request (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  pr_number       text NOT NULL,
  status          text NOT NULL DEFAULT 'OPEN',
  notes           text,
  created_at      timestamptz NOT NULL DEFAULT now(),
  created_by      uuid REFERENCES identity.app_user(id),
  version         integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_pr_number UNIQUE (organization_id, pr_number),
  CONSTRAINT ck_pr_status CHECK (status IN ('OPEN','RFQ','ORDERED','CLOSED','CANCELLED'))
);

CREATE TABLE procurement.purchase_request_line (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  pr_id           uuid NOT NULL REFERENCES procurement.purchase_request(id),
  indent_line_id  uuid NOT NULL REFERENCES indent.indent_line(id),
  product_id      uuid NOT NULL REFERENCES catalog.product(id),
  qty_base        numeric(18,3) NOT NULL,
  CONSTRAINT ck_pr_line_qty CHECK (qty_base > 0)
);

CREATE TABLE procurement.rfq (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  rfq_number      text NOT NULL,
  pr_id           uuid REFERENCES procurement.purchase_request(id),
  status          text NOT NULL DEFAULT 'DRAFT',
  due_at          timestamptz,
  awarded_vendor_id uuid REFERENCES catalog.vendor(id),
  award_justification text,
  created_at      timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_rfq_number UNIQUE (organization_id, rfq_number)
);

CREATE TABLE procurement.quotation (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  rfq_id        uuid NOT NULL REFERENCES procurement.rfq(id),
  vendor_id     uuid NOT NULL REFERENCES catalog.vendor(id),
  received_at   timestamptz NOT NULL DEFAULT now(),
  valid_until   date,
  terms         text,
  document_id   uuid,
  CONSTRAINT uq_quotation UNIQUE (rfq_id, vendor_id)
);

CREATE TABLE procurement.quotation_line (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  quotation_id  uuid NOT NULL REFERENCES procurement.quotation(id) ON DELETE CASCADE,
  product_id    uuid NOT NULL REFERENCES catalog.product(id),
  qty_base      numeric(18,3) NOT NULL,
  unit_price    numeric(18,4) NOT NULL,
  tax_pct       numeric(5,2) NOT NULL DEFAULT 0,
  delivery_days integer
);

CREATE TABLE procurement.sap_po_line (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id     uuid NOT NULL REFERENCES org.organization(id),
  import_batch_id     uuid,
  sap_po_number       text NOT NULL,
  sap_material_code   text NOT NULL,
  sap_material_name   text NOT NULL,
  product_id          uuid REFERENCES catalog.product(id),
  order_qty           numeric(18,3) NOT NULL,
  qty_consumed        numeric(18,3) NOT NULL DEFAULT 0,
  plant               text,
  storage_location    text,
  document_date       date NOT NULL,
  vendor_text         text,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz,
  CONSTRAINT uq_sap_po_line UNIQUE (organization_id, sap_po_number, sap_material_code),
  CONSTRAINT ck_sap_po_qty CHECK (order_qty >= 0 AND qty_consumed >= 0)
);
CREATE INDEX ix_sap_po_product_open ON procurement.sap_po_line (product_id) WHERE qty_consumed < order_qty;

CREATE TABLE procurement.purchase_order (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id       uuid NOT NULL REFERENCES org.organization(id),
  po_number             text NOT NULL,
  external_po_number    text,
  po_type               text NOT NULL DEFAULT 'STANDARD',
  vendor_id             uuid NOT NULL REFERENCES catalog.vendor(id),
  vendor_snapshot       jsonb NOT NULL,
  bill_to_location_id   uuid NOT NULL REFERENCES org.location(id),
  ship_to_location_id   uuid NOT NULL REFERENCES org.location(id),
  status                text NOT NULL DEFAULT 'DRAFT',
  order_date            date NOT NULL DEFAULT current_date,
  currency              char(3) NOT NULL DEFAULT 'INR',
  subtotal              numeric(18,2) NOT NULL DEFAULT 0,
  tax_total             numeric(18,2) NOT NULL DEFAULT 0,
  grand_total           numeric(18,2) NOT NULL DEFAULT 0,
  terms                 text,
  send_suppressed       boolean NOT NULL DEFAULT false,
  sent_at               timestamptz,
  no_po_reason          text,
  workflow_instance_id  uuid REFERENCES workflow.workflow_instance(id),
  legacy_po_raw         text,
  search_tsv            tsvector GENERATED ALWAYS AS (to_tsvector('simple', coalesce(po_number,'') || ' ' || coalesce(external_po_number,''))) STORED,
  created_at            timestamptz NOT NULL DEFAULT now(),
  created_by            uuid,
  updated_at            timestamptz,
  updated_by            uuid,
  version               integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_po_number UNIQUE (organization_id, po_number),
  CONSTRAINT ck_po_type CHECK (po_type IN ('STANDARD','SAP_REFERENCE','NO_PO')),
  CONSTRAINT ck_po_status CHECK (status IN ('DRAFT','PENDING_APPROVAL','APPROVED','REJECTED','SENT','PARTIALLY_RECEIVED','RECEIVED','SHORT_CLOSED','CLOSED','CANCELLED')),
  CONSTRAINT ck_po_no_po_reason CHECK (po_type <> 'NO_PO' OR no_po_reason IS NOT NULL),
  CONSTRAINT ck_po_totals CHECK (subtotal >= 0 AND tax_total >= 0 AND grand_total = subtotal + tax_total)
);
CREATE UNIQUE INDEX uq_po_external ON procurement.purchase_order (organization_id, vendor_id, external_po_number) WHERE external_po_number IS NOT NULL;
CREATE INDEX ix_po_vendor_status ON procurement.purchase_order (vendor_id, status);
CREATE INDEX ix_po_ship_to_open ON procurement.purchase_order (ship_to_location_id) WHERE status IN ('SENT','PARTIALLY_RECEIVED','APPROVED');
CREATE INDEX ix_po_tsv ON procurement.purchase_order USING gin (search_tsv);

CREATE TABLE procurement.purchase_order_line (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  po_id               uuid NOT NULL REFERENCES procurement.purchase_order(id),
  line_no             integer NOT NULL,
  product_id          uuid NOT NULL REFERENCES catalog.product(id),
  product_snapshot    jsonb NOT NULL,
  qty_ordered         numeric(18,3) NOT NULL,
  uom_id              uuid NOT NULL REFERENCES catalog.uom(id),
  qty_base            numeric(18,3) NOT NULL,
  unit_price          numeric(18,4) NOT NULL,
  tax_pct             numeric(5,2) NOT NULL DEFAULT 0,
  amount              numeric(18,2) NOT NULL,
  delivery_date       date,
  delivery_point_code text,
  sap_po_line_id      uuid REFERENCES procurement.sap_po_line(id),
  qty_received        numeric(18,3) NOT NULL DEFAULT 0,
  qty_accepted        numeric(18,3) NOT NULL DEFAULT 0,
  qty_rejected        numeric(18,3) NOT NULL DEFAULT 0,
  status              text NOT NULL DEFAULT 'OPEN',
  CONSTRAINT uq_po_line_no UNIQUE (po_id, line_no),
  CONSTRAINT ck_po_line_qty CHECK (qty_ordered > 0 AND qty_base > 0),
  CONSTRAINT ck_po_line_price CHECK (unit_price >= 0 AND tax_pct >= 0 AND tax_pct <= 100),
  CONSTRAINT ck_po_line_receipts CHECK (qty_received >= 0 AND qty_accepted + qty_rejected = qty_received),
  -- hard ceiling (50%) as last line of defence; configured tolerance (default 10%) enforced by the application
  CONSTRAINT ck_po_line_ceiling CHECK (qty_received <= qty_base * 1.5),
  CONSTRAINT ck_po_line_status CHECK (status IN ('OPEN','PARTIALLY_RECEIVED','RECEIVED','SHORT_CLOSED','CANCELLED'))
);
CREATE INDEX ix_po_line_product ON procurement.purchase_order_line (product_id);

CREATE TABLE procurement.po_line_allocation (
  po_line_id      uuid NOT NULL REFERENCES procurement.purchase_order_line(id),
  indent_line_id  uuid NOT NULL REFERENCES indent.indent_line(id),
  qty_base        numeric(18,3) NOT NULL,
  PRIMARY KEY (po_line_id, indent_line_id),
  CONSTRAINT ck_alloc_qty CHECK (qty_base > 0)
);
CREATE INDEX ix_alloc_indent_line ON procurement.po_line_allocation (indent_line_id);

-- =============================================================================
-- DOCUMENTS (needed by receiving/logistics FKs)
-- =============================================================================
CREATE TABLE docs.document_type (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  code            text NOT NULL,
  name            text NOT NULL,
  allowed_mime    text[] NOT NULL,
  max_bytes       bigint NOT NULL,
  retention_days  integer,
  requires_scan   boolean NOT NULL DEFAULT true,
  CONSTRAINT uq_document_type UNIQUE (organization_id, code),
  CONSTRAINT ck_doc_type_max CHECK (max_bytes > 0)
);

CREATE TABLE docs.document (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id     uuid NOT NULL REFERENCES org.organization(id),
  type_id             uuid NOT NULL REFERENCES docs.document_type(id),
  title               text NOT NULL,
  current_version_no  integer NOT NULL DEFAULT 1,
  status              text NOT NULL DEFAULT 'PENDING_UPLOAD',
  owner_id            uuid REFERENCES identity.app_user(id),
  sensitivity         text NOT NULL DEFAULT 'INTERNAL',
  legal_hold          boolean NOT NULL DEFAULT false,
  search_tsv          tsvector GENERATED ALWAYS AS (to_tsvector('simple', coalesce(title,''))) STORED,
  created_at          timestamptz NOT NULL DEFAULT now(),
  deleted_at          timestamptz,
  CONSTRAINT ck_document_status CHECK (status IN ('PENDING_UPLOAD','PENDING_SCAN','AVAILABLE','QUARANTINED','SUPERSEDED','DELETED')),
  CONSTRAINT ck_document_sensitivity CHECK (sensitivity IN ('PUBLIC','INTERNAL','CONFIDENTIAL','RESTRICTED'))
);
CREATE INDEX ix_document_tsv ON docs.document USING gin (search_tsv);

CREATE TABLE docs.document_version (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  document_id   uuid NOT NULL REFERENCES docs.document(id),
  version_no    integer NOT NULL,
  storage_key   text NOT NULL,
  file_name     text NOT NULL,
  mime_type     text NOT NULL,
  size_bytes    bigint NOT NULL,
  sha256        char(64) NOT NULL,
  scan_status   text NOT NULL DEFAULT 'PENDING',
  scanned_at    timestamptz,
  uploaded_by   uuid REFERENCES identity.app_user(id),
  uploaded_at   timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_document_version UNIQUE (document_id, version_no),
  CONSTRAINT uq_document_storage_key UNIQUE (storage_key),
  CONSTRAINT ck_scan_status CHECK (scan_status IN ('PENDING','CLEAN','INFECTED','ERROR','SKIPPED'))
);

CREATE TABLE docs.document_link (
  document_id   uuid NOT NULL REFERENCES docs.document(id) ON DELETE CASCADE,
  entity_type   text NOT NULL,
  entity_id     uuid NOT NULL,
  role          text NOT NULL DEFAULT 'ATTACHMENT',
  created_at    timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (document_id, entity_type, entity_id, role)
);
CREATE INDEX ix_document_link_entity ON docs.document_link (entity_type, entity_id);

-- =============================================================================
-- RECEIVING
-- =============================================================================
CREATE TABLE receiving.grn (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id   uuid NOT NULL REFERENCES org.organization(id),
  grn_number        text,
  grn_type          text NOT NULL DEFAULT 'PO',
  po_id             uuid REFERENCES procurement.purchase_order(id),
  vendor_id         uuid NOT NULL REFERENCES catalog.vendor(id),
  warehouse_id      uuid NOT NULL REFERENCES org.warehouse(id),
  challan_number    text NOT NULL,
  challan_date      date NOT NULL,
  invoice_number    text,
  invoice_date      date,
  vehicle_number    text,
  received_at       timestamptz NOT NULL DEFAULT now(),
  status            text NOT NULL DEFAULT 'DRAFT',
  posted_at         timestamptz,
  verified_at       timestamptz,
  reversal_of_id    uuid REFERENCES receiving.grn(id),
  pdf_document_id   uuid REFERENCES docs.document(id),
  channel           text NOT NULL DEFAULT 'WEB',
  legacy_grn_number text,
  created_at        timestamptz NOT NULL DEFAULT now(),
  created_by        uuid,
  updated_at        timestamptz,
  updated_by        uuid,
  version           integer NOT NULL DEFAULT 1,
  CONSTRAINT ck_grn_type CHECK (grn_type IN ('PO','NO_PO')),
  CONSTRAINT ck_grn_po CHECK (grn_type = 'NO_PO' OR po_id IS NOT NULL),
  CONSTRAINT ck_grn_status CHECK (status IN ('DRAFT','PENDING_EXCESS_APPROVAL','PENDING_INSPECTION','POSTED','VERIFIED','REVERSED','CANCELLED')),
  CONSTRAINT ck_grn_number_posted CHECK (status NOT IN ('POSTED','VERIFIED','REVERSED') OR grn_number IS NOT NULL)
);
CREATE UNIQUE INDEX uq_grn_number ON receiving.grn (organization_id, grn_number) WHERE grn_number IS NOT NULL;
CREATE UNIQUE INDEX uq_grn_challan_posted ON receiving.grn (organization_id, vendor_id, lower(challan_number), challan_date)
  WHERE status IN ('POSTED','VERIFIED') AND reversal_of_id IS NULL;
CREATE INDEX ix_grn_po ON receiving.grn (po_id);
CREATE INDEX ix_grn_warehouse_date ON receiving.grn (warehouse_id, received_at DESC);

CREATE TABLE receiving.grn_line (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  grn_id              uuid NOT NULL REFERENCES receiving.grn(id),
  po_line_id          uuid REFERENCES procurement.purchase_order_line(id),
  product_id          uuid NOT NULL REFERENCES catalog.product(id),
  qty_received        numeric(18,3) NOT NULL,
  qty_accepted        numeric(18,3) NOT NULL,
  qty_rejected        numeric(18,3) NOT NULL DEFAULT 0,
  qty_damaged         numeric(18,3) NOT NULL DEFAULT 0,
  reject_reason_code  text,
  batch_no            text,
  mfg_date            date,
  expiry_date         date,
  remarks             text,
  CONSTRAINT ck_grn_line_nonneg CHECK (qty_received >= 0 AND qty_accepted >= 0 AND qty_rejected >= 0 AND qty_damaged >= 0),
  CONSTRAINT ck_grn_line_balance CHECK (qty_received = qty_accepted + qty_rejected),
  CONSTRAINT ck_grn_line_damaged CHECK (qty_damaged <= qty_rejected),
  CONSTRAINT ck_grn_line_expiry CHECK (expiry_date IS NULL OR mfg_date IS NULL OR expiry_date >= mfg_date)
);
CREATE INDEX ix_grn_line_grn ON receiving.grn_line (grn_id);
CREATE INDEX ix_grn_line_po_line ON receiving.grn_line (po_line_id);

CREATE TABLE receiving.grn_line_serial (
  grn_line_id uuid NOT NULL REFERENCES receiving.grn_line(id),
  product_id  uuid NOT NULL REFERENCES catalog.product(id),
  serial_no   text NOT NULL,
  PRIMARY KEY (grn_line_id, serial_no)
);
CREATE UNIQUE INDEX uq_serial_per_product ON receiving.grn_line_serial (product_id, serial_no);

CREATE TABLE receiving.inspection (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  grn_id        uuid NOT NULL REFERENCES receiving.grn(id),
  inspector_id  uuid NOT NULL REFERENCES identity.app_user(id),
  result        text NOT NULL,
  remarks       text,
  inspected_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ck_inspection_result CHECK (result IN ('PASSED','PARTIALLY_PASSED','FAILED'))
);

-- =============================================================================
-- LOGISTICS
-- =============================================================================
CREATE TABLE logistics.transfer_order (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id       uuid NOT NULL REFERENCES org.organization(id),
  transfer_number       text NOT NULL,
  source_location_id    uuid NOT NULL REFERENCES org.location(id),
  dest_location_id      uuid NOT NULL REFERENCES org.location(id),
  status                text NOT NULL DEFAULT 'PENDING_PLANNING',
  origin                text NOT NULL,
  reason                text,
  created_at            timestamptz NOT NULL DEFAULT now(),
  created_by            uuid,
  updated_at            timestamptz,
  version               integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_transfer_number UNIQUE (organization_id, transfer_number),
  CONSTRAINT ck_transfer_distinct CHECK (source_location_id <> dest_location_id),
  CONSTRAINT ck_transfer_origin CHECK (origin IN ('HOD_APPROVAL','MANUAL')),
  CONSTRAINT ck_transfer_status CHECK (status IN ('PENDING_APPROVAL','PENDING_PLANNING','STN_ISSUED','PARTIALLY_DISPATCHED','DISPATCHED','PARTIALLY_RECEIVED','RECEIVED','DISCREPANCY_OPEN','CLOSED','CANCELLED'))
);
CREATE INDEX ix_transfer_route_status ON logistics.transfer_order (source_location_id, dest_location_id, status);

CREATE TABLE logistics.transfer_order_line (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  transfer_id     uuid NOT NULL REFERENCES logistics.transfer_order(id),
  indent_line_id  uuid REFERENCES indent.indent_line(id),
  product_id      uuid NOT NULL REFERENCES catalog.product(id),
  qty_base        numeric(18,3) NOT NULL,
  qty_on_stn      numeric(18,3) NOT NULL DEFAULT 0,
  status          text NOT NULL DEFAULT 'OPEN',
  CONSTRAINT ck_to_line_qty CHECK (qty_base > 0 AND qty_on_stn >= 0 AND qty_on_stn <= qty_base)
);
CREATE INDEX ix_to_line_transfer ON logistics.transfer_order_line (transfer_id);

CREATE TABLE logistics.stn (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id     uuid NOT NULL REFERENCES org.organization(id),
  stn_number          text NOT NULL,
  transfer_id         uuid REFERENCES logistics.transfer_order(id),  -- null for location-initiated STN (STN-012)
  source_warehouse_id uuid NOT NULL REFERENCES org.warehouse(id),
  dest_warehouse_id   uuid NOT NULL REFERENCES org.warehouse(id),
  transporter_name    text,
  vehicle_number      text,
  driver_name         text,
  driver_phone_e164   text,
  eway_bill_number    text,
  expected_arrival    timestamptz,
  status              text NOT NULL DEFAULT 'DRAFT',
  posted_at           timestamptz,
  posted_by           uuid,
  dispatched_at       timestamptz,
  received_at         timestamptz,
  pdf_document_id     uuid REFERENCES docs.document(id),
  legacy_stn_number   text,
  created_at          timestamptz NOT NULL DEFAULT now(),
  created_by          uuid,
  updated_at          timestamptz,
  version             integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_stn_number UNIQUE (organization_id, stn_number),
  CONSTRAINT ck_stn_distinct CHECK (source_warehouse_id <> dest_warehouse_id),
  CONSTRAINT ck_stn_status CHECK (status IN ('DRAFT','STN_ISSUED','PARTIALLY_DISPATCHED','DISPATCHED','IN_TRANSIT','PARTIALLY_RECEIVED','RECEIVED','DISCREPANCY_OPEN','CLOSED','CANCELLED'))
);
CREATE INDEX ix_stn_dest_open ON logistics.stn (dest_warehouse_id) WHERE status IN ('DISPATCHED','IN_TRANSIT','PARTIALLY_RECEIVED');
CREATE INDEX ix_stn_source_open ON logistics.stn (source_warehouse_id) WHERE status IN ('STN_ISSUED','PARTIALLY_DISPATCHED');

CREATE TABLE logistics.stn_line (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stn_id          uuid NOT NULL REFERENCES logistics.stn(id),
  to_line_id      uuid REFERENCES logistics.transfer_order_line(id),
  product_id      uuid NOT NULL REFERENCES catalog.product(id),
  batch_id        uuid,
  qty_planned     numeric(18,3) NOT NULL,
  qty_dispatched  numeric(18,3) NOT NULL DEFAULT 0,
  qty_received    numeric(18,3) NOT NULL DEFAULT 0,
  qty_rejected    numeric(18,3) NOT NULL DEFAULT 0,
  qty_resolved    numeric(18,3) NOT NULL DEFAULT 0,
  qty_in_transit  numeric(18,3) GENERATED ALWAYS AS (qty_dispatched - qty_received - qty_resolved) STORED,
  CONSTRAINT ck_stn_line_planned CHECK (qty_planned > 0),
  CONSTRAINT ck_stn_line_dispatch CHECK (qty_dispatched >= 0 AND qty_dispatched <= qty_planned),
  CONSTRAINT ck_stn_line_receipt CHECK (qty_received >= 0 AND qty_rejected >= 0 AND qty_resolved >= 0
                                        AND qty_received + qty_resolved <= qty_dispatched)
);
CREATE INDEX ix_stn_line_stn ON logistics.stn_line (stn_id);

CREATE TABLE logistics.stn_receipt (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  stn_id          uuid NOT NULL REFERENCES logistics.stn(id),
  receipt_number  text NOT NULL,
  warehouse_id    uuid NOT NULL REFERENCES org.warehouse(id),
  received_by     uuid NOT NULL REFERENCES identity.app_user(id),
  received_at     timestamptz NOT NULL DEFAULT now(),
  legacy_grn_number text,
  CONSTRAINT uq_stn_receipt_number UNIQUE (organization_id, receipt_number)
);

CREATE TABLE logistics.stn_receipt_line (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  receipt_id    uuid NOT NULL REFERENCES logistics.stn_receipt(id),
  stn_line_id   uuid NOT NULL REFERENCES logistics.stn_line(id),
  qty_received  numeric(18,3) NOT NULL,
  qty_accepted  numeric(18,3) NOT NULL,
  qty_rejected  numeric(18,3) NOT NULL DEFAULT 0,
  reason        text,
  CONSTRAINT ck_stn_rl_balance CHECK (qty_received >= 0 AND qty_accepted >= 0 AND qty_rejected >= 0 AND qty_received = qty_accepted + qty_rejected)
);

CREATE TABLE logistics.transit_discrepancy (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  stn_line_id   uuid NOT NULL REFERENCES logistics.stn_line(id),
  type          text NOT NULL,
  qty           numeric(18,3) NOT NULL,
  status        text NOT NULL DEFAULT 'OPEN',
  resolution    text,
  remarks       text,
  resolved_by   uuid REFERENCES identity.app_user(id),
  resolved_at   timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ck_disc_type CHECK (type IN ('SHORT','DAMAGED','EXCESS')),
  CONSTRAINT ck_disc_qty CHECK (qty > 0),
  CONSTRAINT ck_disc_status CHECK (status IN ('OPEN','PENDING_APPROVAL','RESOLVED')),
  CONSTRAINT ck_disc_resolution CHECK (resolution IS NULL OR resolution IN ('RETURN_TO_SOURCE','WRITE_OFF','LATE_RECEIPT')),
  CONSTRAINT ck_disc_resolved CHECK ((status = 'RESOLVED') = (resolution IS NOT NULL AND resolved_at IS NOT NULL))
);
CREATE INDEX ix_disc_open ON logistics.transit_discrepancy (created_at) WHERE status <> 'RESOLVED';

-- =============================================================================
-- INVENTORY LEDGER
-- =============================================================================
CREATE TABLE inventory.batch (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  product_id      uuid NOT NULL REFERENCES catalog.product(id),
  batch_no        text NOT NULL,
  mfg_date        date,
  expiry_date     date,
  CONSTRAINT uq_batch UNIQUE (organization_id, product_id, batch_no)
);

-- batch_key: batch id or the all-zero sentinel for non-batch products (keeps PK non-null)
CREATE TABLE inventory.stock_balance (
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  warehouse_id    uuid NOT NULL REFERENCES org.warehouse(id),
  product_id      uuid NOT NULL REFERENCES catalog.product(id),
  batch_key       uuid NOT NULL DEFAULT '00000000-0000-0000-0000-000000000000',
  qty_on_hand     numeric(18,3) NOT NULL DEFAULT 0,
  qty_reserved    numeric(18,3) NOT NULL DEFAULT 0,
  qty_available   numeric(18,3) GENERATED ALWAYS AS (qty_on_hand - qty_reserved) STORED,
  avg_unit_cost   numeric(18,4),
  last_txn_id     uuid,
  last_txn_at     timestamptz,
  version         integer NOT NULL DEFAULT 1,
  PRIMARY KEY (warehouse_id, product_id, batch_key),
  CONSTRAINT ck_balance_nonneg CHECK (qty_on_hand >= 0),
  CONSTRAINT ck_balance_reserved CHECK (qty_reserved >= 0 AND qty_reserved <= qty_on_hand)
);
CREATE INDEX ix_balance_product ON inventory.stock_balance (product_id);

CREATE TABLE inventory.stock_transaction (
  id                        uuid NOT NULL DEFAULT gen_random_uuid(),
  organization_id           uuid NOT NULL,
  occurred_at               timestamptz NOT NULL,
  posted_at                 timestamptz NOT NULL DEFAULT now(),
  warehouse_id              uuid NOT NULL,
  product_id                uuid NOT NULL,
  batch_key                 uuid NOT NULL DEFAULT '00000000-0000-0000-0000-000000000000',
  movement_type             text NOT NULL,
  direction                 smallint NOT NULL,
  quantity                  numeric(18,3) NOT NULL,
  qty_before                numeric(18,3) NOT NULL,
  qty_after                 numeric(18,3) NOT NULL,
  unit_cost                 numeric(18,4),
  value                     numeric(18,2),
  source_type               text NOT NULL,
  source_id                 uuid NOT NULL,
  source_line_id            uuid,
  source_number             text,
  counterparty_warehouse_id uuid,
  reason_code               text,
  remarks                   text,
  performed_by              uuid NOT NULL,
  channel                   text NOT NULL DEFAULT 'WEB',
  idempotency_key           text NOT NULL,
  reversal_of_id            uuid,
  PRIMARY KEY (id, occurred_at),
  CONSTRAINT uq_stock_txn_idem UNIQUE (organization_id, idempotency_key, occurred_at),
  CONSTRAINT ck_txn_direction CHECK (direction IN (-1, 1)),
  CONSTRAINT ck_txn_quantity CHECK (quantity > 0),
  CONSTRAINT ck_txn_arith CHECK (qty_after = qty_before + direction * quantity),
  CONSTRAINT ck_txn_movement CHECK (movement_type IN ('OPENING','GRN_RECEIPT','GRN_REVERSAL','RETURN_TO_VENDOR','TRANSFER_OUT','TRANSIT_IN','TRANSIT_OUT','TRANSFER_IN','TRANSIT_WRITE_OFF','ISSUE_ADVANCE_SALE','ISSUE_GENERAL_SALE','ISSUE_OTHER_SALE','SALE_REVERSAL','RETURN_FROM_MPP','ISSUE_INTERNAL','ADJUSTMENT_IN','ADJUSTMENT_OUT','DAMAGE','EXPIRY','DISPOSAL','CORRECTION'))
) PARTITION BY RANGE (occurred_at);
-- NOTE: idempotency uniqueness includes the partition key; the posting service derives occurred_at
-- deterministically from the source document (document date/time), so replays map to the same partition.
CREATE INDEX ix_txn_wh_prod_time ON inventory.stock_transaction (warehouse_id, product_id, occurred_at);
CREATE INDEX ix_txn_source ON inventory.stock_transaction (source_type, source_id);
CREATE TABLE inventory.stock_transaction_default PARTITION OF inventory.stock_transaction DEFAULT;
CREATE TABLE inventory.stock_transaction_2026_09 PARTITION OF inventory.stock_transaction FOR VALUES FROM ('2026-09-01') TO ('2026-10-01');
CREATE TABLE inventory.stock_transaction_2026_10 PARTITION OF inventory.stock_transaction FOR VALUES FROM ('2026-10-01') TO ('2026-11-01');
CREATE TABLE inventory.stock_transaction_2026_11 PARTITION OF inventory.stock_transaction FOR VALUES FROM ('2026-11-01') TO ('2026-12-01');
CREATE TRIGGER tg_stock_txn_append_only BEFORE UPDATE OR DELETE ON inventory.stock_transaction
  FOR EACH ROW EXECUTE FUNCTION public.forbid_mutation();

CREATE TABLE inventory.stock_adjustment (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  adj_number      text NOT NULL,
  warehouse_id    uuid NOT NULL REFERENCES org.warehouse(id),
  reason_code     text NOT NULL,
  remarks         text NOT NULL,
  status          text NOT NULL DEFAULT 'PENDING_APPROVAL',
  requested_by    uuid NOT NULL REFERENCES identity.app_user(id),
  approved_by     uuid REFERENCES identity.app_user(id),
  workflow_instance_id uuid REFERENCES workflow.workflow_instance(id),
  created_at      timestamptz NOT NULL DEFAULT now(),
  posted_at       timestamptz,
  version         integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_adj_number UNIQUE (organization_id, adj_number),
  CONSTRAINT ck_adj_status CHECK (status IN ('PENDING_APPROVAL','APPROVED','POSTED','REJECTED','CANCELLED')),
  CONSTRAINT ck_adj_sod CHECK (approved_by IS NULL OR approved_by <> requested_by)
);

CREATE TABLE inventory.stock_adjustment_line (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  adjustment_id   uuid NOT NULL REFERENCES inventory.stock_adjustment(id),
  product_id      uuid NOT NULL REFERENCES catalog.product(id),
  batch_key       uuid NOT NULL DEFAULT '00000000-0000-0000-0000-000000000000',
  book_qty        numeric(18,3) NOT NULL,
  qty_delta       numeric(18,3) NOT NULL,
  counted_qty     numeric(18,3),
  CONSTRAINT ck_adj_line_delta CHECK (qty_delta <> 0)
);

CREATE TABLE inventory.physical_count (
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  location_id     uuid NOT NULL REFERENCES org.location(id),
  product_id      uuid NOT NULL REFERENCES catalog.product(id),
  physical_qty    integer,
  counted_by      uuid REFERENCES identity.app_user(id),
  counted_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (location_id, product_id),
  CONSTRAINT ck_physical_nonneg CHECK (physical_qty IS NULL OR physical_qty >= 0)
);

CREATE TABLE inventory.stock_count (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  count_number    text NOT NULL,
  warehouse_id    uuid NOT NULL REFERENCES org.warehouse(id),
  status          text NOT NULL DEFAULT 'OPEN',
  snapshot_at     timestamptz NOT NULL DEFAULT now(),
  submitted_at    timestamptz,
  adjustment_id   uuid REFERENCES inventory.stock_adjustment(id),
  CONSTRAINT uq_count_number UNIQUE (organization_id, count_number),
  CONSTRAINT ck_count_status CHECK (status IN ('OPEN','SUBMITTED','ADJUSTED','CANCELLED'))
);

CREATE TABLE inventory.stock_count_line (
  count_id      uuid NOT NULL REFERENCES inventory.stock_count(id),
  product_id    uuid NOT NULL REFERENCES catalog.product(id),
  batch_key     uuid NOT NULL DEFAULT '00000000-0000-0000-0000-000000000000',
  book_qty      numeric(18,3) NOT NULL,
  counted_qty   numeric(18,3),
  counted_by    uuid REFERENCES identity.app_user(id),
  counted_at    timestamptz,
  PRIMARY KEY (count_id, product_id, batch_key),
  CONSTRAINT ck_count_nonneg CHECK (counted_qty IS NULL OR counted_qty >= 0)
);

-- Period view (§24.12): opening/received/issued/transferred/adjusted/closing
CREATE OR REPLACE FUNCTION inventory.stock_period(p_warehouse uuid, p_from timestamptz, p_to timestamptz)
RETURNS TABLE (product_id uuid, opening_quantity numeric, received_quantity numeric, issued_quantity numeric,
               transferred_quantity numeric, adjusted_quantity numeric, closing_quantity numeric)
LANGUAGE sql STABLE AS $$
  SELECT t.product_id,
    coalesce(sum(t.direction * t.quantity) FILTER (WHERE t.occurred_at < p_from), 0),
    coalesce(sum(t.quantity) FILTER (WHERE t.occurred_at >= p_from AND t.occurred_at < p_to
             AND t.movement_type IN ('OPENING','GRN_RECEIPT','TRANSFER_IN','RETURN_FROM_MPP','SALE_REVERSAL','TRANSIT_IN')), 0),
    coalesce(sum(t.quantity) FILTER (WHERE t.occurred_at >= p_from AND t.occurred_at < p_to
             AND t.movement_type IN ('ISSUE_ADVANCE_SALE','ISSUE_GENERAL_SALE','ISSUE_OTHER_SALE','ISSUE_INTERNAL','RETURN_TO_VENDOR','GRN_REVERSAL','TRANSIT_OUT')), 0),
    coalesce(sum(t.quantity) FILTER (WHERE t.occurred_at >= p_from AND t.occurred_at < p_to
             AND t.movement_type = 'TRANSFER_OUT'), 0),
    coalesce(sum(t.direction * t.quantity) FILTER (WHERE t.occurred_at >= p_from AND t.occurred_at < p_to
             AND t.movement_type IN ('ADJUSTMENT_IN','ADJUSTMENT_OUT','DAMAGE','EXPIRY','DISPOSAL','CORRECTION','TRANSIT_WRITE_OFF')), 0),
    coalesce(sum(t.direction * t.quantity) FILTER (WHERE t.occurred_at < p_to), 0)
  FROM inventory.stock_transaction t
  WHERE t.warehouse_id = p_warehouse AND t.occurred_at < p_to
  GROUP BY t.product_id
$$;

-- =============================================================================
-- RECON (cycles) — defined before MPP sales which reference cycles
-- =============================================================================
CREATE TABLE recon.cycle_month (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  year            integer NOT NULL,
  month           integer NOT NULL,
  name            text NOT NULL,
  description     text,
  is_locked       boolean NOT NULL DEFAULT false,
  locked_at       timestamptz,
  locked_by       uuid REFERENCES identity.app_user(id),
  lock_reason     text,
  created_by      uuid REFERENCES identity.app_user(id),
  created_at      timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ck_cycle_month_lock CHECK (NOT is_locked OR locked_at IS NOT NULL),
  CONSTRAINT uq_cycle_month UNIQUE (organization_id, year, month),
  CONSTRAINT ck_cycle_month CHECK (month BETWEEN 1 AND 12 AND year BETWEEN 2020 AND 2100)
);

CREATE TABLE recon.payment_cycle (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id   uuid NOT NULL REFERENCES org.organization(id),
  cycle_month_id    uuid NOT NULL REFERENCES recon.cycle_month(id),
  cycle_no          integer NOT NULL,
  name              text NOT NULL,
  sap_cycle_number  text,
  start_date        date NOT NULL,
  end_date          date NOT NULL,
  status            text NOT NULL DEFAULT 'PLANNED',
  closed_at         timestamptz,
  legacy_cycle_id   bigint,
  version           integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_cycle_no UNIQUE (cycle_month_id, cycle_no),
  CONSTRAINT ck_cycle_dates CHECK (start_date <= end_date),
  CONSTRAINT ck_cycle_status CHECK (status IN ('PLANNED','ACTIVE','INACTIVE','RECONCILING','CLOSED')),
  CONSTRAINT ex_cycle_overlap EXCLUDE USING gist (organization_id WITH =, daterange(start_date, end_date, '[]') WITH &&)
);
CREATE UNIQUE INDEX uq_cycle_sap_number ON recon.payment_cycle (organization_id, sap_cycle_number) WHERE sap_cycle_number IS NOT NULL;
CREATE UNIQUE INDEX uq_cycle_single_active ON recon.payment_cycle (organization_id) WHERE status = 'ACTIVE';

-- =============================================================================
-- MPP DISTRIBUTION
-- =============================================================================
CREATE TABLE mpp.advance_sale (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id     uuid NOT NULL REFERENCES org.organization(id),
  sale_number         text NOT NULL,
  sale_code           char(10) NOT NULL,
  location_id         uuid NOT NULL REFERENCES org.location(id),
  warehouse_id        uuid NOT NULL REFERENCES org.warehouse(id),
  mpp_id              uuid NOT NULL REFERENCES catalog.mpp(id),
  mpp_snapshot        jsonb NOT NULL,
  cycle_id            uuid NOT NULL REFERENCES recon.payment_cycle(id),
  sale_date           date NOT NULL,
  status              text NOT NULL DEFAULT 'ISSUED',
  pod_status          text NOT NULL DEFAULT 'PENDING',
  receipt_document_id uuid REFERENCES docs.document(id),
  receipt_status      text NOT NULL DEFAULT 'PENDING',
  channel             text NOT NULL DEFAULT 'WEB',
  client_ref          uuid NOT NULL,
  client_created_at   timestamptz,
  cancelled_reason    text,
  legacy_advance_sale_ids bigint[] NOT NULL DEFAULT '{}',
  created_at          timestamptz NOT NULL DEFAULT now(),
  created_by          uuid NOT NULL REFERENCES identity.app_user(id),
  updated_at          timestamptz,
  version             integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_sale_code UNIQUE (organization_id, sale_code),
  CONSTRAINT uq_sale_number UNIQUE (organization_id, sale_number),
  CONSTRAINT uq_sale_client_ref UNIQUE (organization_id, created_by, client_ref),
  CONSTRAINT ck_sale_code CHECK (sale_code ~ '^[0-9]{10}$'),
  CONSTRAINT ck_sale_status CHECK (status IN ('ISSUED','DELIVERED','RECONCILED','CANCELLED')),
  CONSTRAINT ck_sale_pod CHECK (pod_status IN ('PENDING','UPLOADED','NOT_REQUIRED')),
  CONSTRAINT ck_sale_receipt CHECK (receipt_status IN ('PENDING','GENERATING','READY','FAILED')),
  CONSTRAINT ck_sale_channel CHECK (channel IN ('WEB','MOBILE','MOBILE_OFFLINE','API'))
);
CREATE INDEX ix_sale_location_cycle ON mpp.advance_sale (location_id, cycle_id);
CREATE INDEX ix_sale_mpp ON mpp.advance_sale (mpp_id, sale_date DESC);
CREATE INDEX ix_sale_pod_pending ON mpp.advance_sale (created_by) WHERE pod_status = 'PENDING' AND status = 'ISSUED';

CREATE TABLE mpp.advance_sale_line (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sale_id           uuid NOT NULL REFERENCES mpp.advance_sale(id),
  line_no           integer NOT NULL,
  product_id        uuid NOT NULL REFERENCES catalog.product(id),
  product_snapshot  jsonb NOT NULL,
  qty               numeric(18,3) NOT NULL,
  uom_id            uuid NOT NULL REFERENCES catalog.uom(id),
  qty_base          numeric(18,3) NOT NULL,
  CONSTRAINT uq_sale_line UNIQUE (sale_id, line_no),
  CONSTRAINT ck_sale_line_qty CHECK (qty > 0 AND qty_base > 0)
);

CREATE TABLE recon.sale_entry (
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  cycle_id        uuid NOT NULL REFERENCES recon.payment_cycle(id),
  location_id     uuid NOT NULL REFERENCES org.location(id),
  mpp_id          uuid NOT NULL REFERENCES catalog.mpp(id),
  product_id      uuid NOT NULL REFERENCES catalog.product(id),
  advance_qty     numeric(18,3) NOT NULL DEFAULT 0,
  sap_qty         numeric(18,3) NOT NULL DEFAULT 0,
  status          text GENERATED ALWAYS AS (
                    CASE WHEN sap_qty = advance_qty THEN 'OK'
                         WHEN sap_qty > advance_qty THEN 'OVER_SOLD'
                         WHEN sap_qty > 0 THEN 'UNDER_SOLD'
                         ELSE 'NOT_SOLD' END) STORED,
  updated_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (cycle_id, location_id, mpp_id, product_id),
  CONSTRAINT ck_sale_entry_nonneg CHECK (advance_qty >= 0 AND sap_qty >= 0)
);

CREATE TABLE mpp.general_sale (
  id                        uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id           uuid NOT NULL REFERENCES org.organization(id),
  sale_number               text NOT NULL,
  sale_code                 char(10),
  origin                    text NOT NULL,
  reconciliation_record_id  uuid,
  location_id               uuid NOT NULL REFERENCES org.location(id),
  mpp_id                    uuid NOT NULL REFERENCES catalog.mpp(id),
  cycle_id                  uuid NOT NULL REFERENCES recon.payment_cycle(id),
  status                    text NOT NULL DEFAULT 'PENDING',
  dispatched_at             timestamptz,
  delivered_at              timestamptz,
  client_ref                uuid,
  created_at                timestamptz NOT NULL DEFAULT now(),
  created_by                uuid REFERENCES identity.app_user(id),
  version                   integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_general_sale_number UNIQUE (organization_id, sale_number),
  CONSTRAINT ck_gs_origin CHECK (origin IN ('RECONCILIATION','MANUAL')),
  CONSTRAINT ck_gs_status CHECK (status IN ('PENDING','ISSUED','DELIVERED','RECONCILED','CANCELLED'))
);
CREATE UNIQUE INDEX uq_general_sale_code ON mpp.general_sale (organization_id, sale_code) WHERE sale_code IS NOT NULL;

CREATE TABLE mpp.general_sale_line (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  general_sale_id uuid NOT NULL REFERENCES mpp.general_sale(id),
  product_id      uuid NOT NULL REFERENCES catalog.product(id),
  qty_base        numeric(18,3) NOT NULL,
  CONSTRAINT ck_gs_line_qty CHECK (qty_base > 0)
);

CREATE TABLE mpp.pod (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id       uuid NOT NULL REFERENCES org.organization(id),
  subject_type          text NOT NULL,
  subject_id            uuid NOT NULL,
  document_id           uuid NOT NULL REFERENCES docs.document(id),
  verified_code_match   boolean NOT NULL,
  captured_at           timestamptz NOT NULL,
  geo_lat               double precision,
  geo_lng               double precision,
  uploaded_by           uuid NOT NULL REFERENCES identity.app_user(id),
  status                text NOT NULL DEFAULT 'ACTIVE',
  created_at            timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ck_pod_subject CHECK (subject_type IN ('ADVANCE_SALE','GENERAL_SALE','OTHER_SALE','STN')),
  CONSTRAINT ck_pod_status CHECK (status IN ('ACTIVE','SUPERSEDED')),
  CONSTRAINT ck_pod_verified CHECK (verified_code_match)
);
CREATE UNIQUE INDEX uq_pod_active ON mpp.pod (subject_type, subject_id) WHERE status = 'ACTIVE';

-- =============================================================================
-- RECON (imports, sheets, ledger)
-- =============================================================================
CREATE TABLE recon.reconciliation_sheet (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id     uuid NOT NULL REFERENCES org.organization(id),
  cycle_id            uuid NOT NULL REFERENCES recon.payment_cycle(id),
  version_no          integer NOT NULL,
  import_batch_id     uuid,
  file_document_id    uuid REFERENCES docs.document(id),
  file_sha256         char(64) NOT NULL,
  status              text NOT NULL DEFAULT 'UPLOADED',
  total_records       integer NOT NULL DEFAULT 0,
  perfect_match_count integer NOT NULL DEFAULT 0,
  under_recorded_count integer NOT NULL DEFAULT 0,
  over_recorded_count integer NOT NULL DEFAULT 0,
  not_recorded_count  integer NOT NULL DEFAULT 0,
  exception_count     integer NOT NULL DEFAULT 0,
  uploaded_by         uuid NOT NULL REFERENCES identity.app_user(id),
  uploaded_at         timestamptz NOT NULL DEFAULT now(),
  processed_at        timestamptz,
  published_at        timestamptz,
  superseded_by_id    uuid REFERENCES recon.reconciliation_sheet(id),
  legacy_sheet_id     bigint,
  CONSTRAINT uq_recon_sheet_version UNIQUE (cycle_id, version_no),
  CONSTRAINT uq_recon_sheet_file UNIQUE (cycle_id, file_sha256),
  CONSTRAINT ck_recon_sheet_status CHECK (status IN ('UPLOADED','VALIDATING','VALIDATION_FAILED','PREVIEW_READY','PROCESSING','PROCESSED','PROCESSED_WITH_EXCEPTIONS','FAILED','DISCARDED','PUBLISHED','SUPERSEDED'))
);

CREATE TABLE recon.reconciliation_record (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sheet_id              uuid NOT NULL REFERENCES recon.reconciliation_sheet(id),
  location_id           uuid REFERENCES org.location(id),
  location_raw          text NOT NULL,
  mpp_id                uuid REFERENCES catalog.mpp(id),
  mpp_code_raw          text NOT NULL,
  mpp_name_raw          text,
  product_id            uuid REFERENCES catalog.product(id),
  product_raw           text NOT NULL,
  advance_qty           numeric(18,3) NOT NULL DEFAULT 0,
  sap_qty               numeric(18,3) NOT NULL DEFAULT 0,
  input_status          text,
  input_match_quality   text,
  computed_status       text,
  to_be_sent            numeric(18,3) NOT NULL DEFAULT 0,
  to_be_deducted        numeric(18,3) NOT NULL DEFAULT 0,
  is_service            boolean NOT NULL DEFAULT false,
  exception_code        text,
  exception_resolution  text,
  acknowledged_by       uuid REFERENCES identity.app_user(id),
  acknowledged_at       timestamptz,
  ack_comment           text,
  CONSTRAINT uq_recon_record UNIQUE (sheet_id, location_raw, mpp_code_raw, product_raw),
  CONSTRAINT ck_recon_computed CHECK (computed_status IS NULL OR computed_status IN ('PERFECT_MATCH','UNDER_RECORDED','OVER_RECORDED','NOT_RECORDED')),
  CONSTRAINT ck_recon_amounts CHECK (to_be_sent >= 0 AND to_be_deducted >= 0 AND NOT (to_be_sent > 0 AND to_be_deducted > 0)),
  CONSTRAINT ck_recon_mapped CHECK (exception_code IS NOT NULL OR computed_status = 'NOT_RECORDED' OR (mpp_id IS NOT NULL AND product_id IS NOT NULL) OR computed_status IS NULL)
);
CREATE INDEX ix_recon_record_location ON recon.reconciliation_record (location_id, sheet_id);
CREATE INDEX ix_recon_record_exceptions ON recon.reconciliation_record (sheet_id) WHERE exception_code IS NOT NULL;

ALTER TABLE mpp.general_sale
  ADD CONSTRAINT fk_general_sale_record FOREIGN KEY (reconciliation_record_id) REFERENCES recon.reconciliation_record(id);

-- Ledger formula per OQ-020 proposal: closing = opening + advance − SAP
-- (positive = still to be deducted from MPP; negative = to be sent/credited to MPP).
CREATE TABLE recon.mpp_product_ledger (
  organization_id   uuid NOT NULL REFERENCES org.organization(id),
  mpp_id            uuid NOT NULL REFERENCES catalog.mpp(id),
  product_id        uuid NOT NULL REFERENCES catalog.product(id),
  cycle_id          uuid NOT NULL REFERENCES recon.payment_cycle(id),
  opening_balance   numeric(18,3) NOT NULL DEFAULT 0,
  advance_qty       numeric(18,3) NOT NULL DEFAULT 0,
  sap_qty           numeric(18,3) NOT NULL DEFAULT 0,
  closing_balance   numeric(18,3) GENERATED ALWAYS AS (opening_balance + advance_qty - sap_qty) STORED,
  source_record_id  uuid REFERENCES recon.reconciliation_record(id),
  computed_at       timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (mpp_id, product_id, cycle_id)
);
CREATE INDEX ix_ledger_cycle ON recon.mpp_product_ledger (cycle_id);

CREATE TABLE recon.cycle_product_summary (
  cycle_id          uuid NOT NULL REFERENCES recon.payment_cycle(id),
  product_id        uuid NOT NULL REFERENCES catalog.product(id),
  total_advance     numeric(18,3) NOT NULL DEFAULT 0,
  total_sap         numeric(18,3) NOT NULL DEFAULT 0,
  total_to_send     numeric(18,3) NOT NULL DEFAULT 0,
  total_to_deduct   numeric(18,3) NOT NULL DEFAULT 0,
  mpp_count         integer NOT NULL DEFAULT 0,
  reconciled_count  integer NOT NULL DEFAULT 0,
  refreshed_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (cycle_id, product_id)
);

CREATE TABLE recon.location_notification (
  sheet_id        uuid NOT NULL REFERENCES recon.reconciliation_sheet(id),
  location_id     uuid NOT NULL REFERENCES org.location(id),
  status          text NOT NULL DEFAULT 'PENDING',
  sent_at         timestamptz,
  viewed_at       timestamptz,
  acknowledged_at timestamptz,
  acknowledged_by uuid REFERENCES identity.app_user(id),
  comment         text,
  PRIMARY KEY (sheet_id, location_id),
  CONSTRAINT ck_loc_notif_status CHECK (status IN ('PENDING','SENT','VIEWED','ACKNOWLEDGED'))
);

