-- FINANCE
-- =============================================================================
CREATE TABLE finance.invoice (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  vendor_id       uuid NOT NULL REFERENCES catalog.vendor(id),
  invoice_number  text NOT NULL,
  invoice_date    date NOT NULL,
  fiscal_year     text NOT NULL,
  po_id           uuid REFERENCES procurement.purchase_order(id),
  vendor_gstin    text,
  subtotal        numeric(18,2) NOT NULL DEFAULT 0,
  tax_total       numeric(18,2) NOT NULL DEFAULT 0,
  grand_total     numeric(18,2) NOT NULL DEFAULT 0,
  status          text NOT NULL DEFAULT 'DRAFT',
  payment_status  text NOT NULL DEFAULT 'UNPAID',
  document_id     uuid REFERENCES docs.document(id),
  created_at      timestamptz NOT NULL DEFAULT now(),
  created_by      uuid,
  updated_at      timestamptz,
  version         integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_invoice UNIQUE (organization_id, vendor_id, invoice_number, fiscal_year),
  CONSTRAINT ck_invoice_status CHECK (status IN ('DRAFT','SUBMITTED','MATCHED','EXCEPTION','APPROVED','ON_HOLD','REJECTED')),
  CONSTRAINT ck_invoice_payment CHECK (payment_status IN ('UNPAID','SCHEDULED','PARTIALLY_PAID','PAID')),
  CONSTRAINT ck_invoice_totals CHECK (grand_total = subtotal + tax_total)
);

CREATE TABLE finance.invoice_line (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id    uuid NOT NULL REFERENCES finance.invoice(id),
  po_line_id    uuid REFERENCES procurement.purchase_order_line(id),
  grn_line_ids  uuid[] NOT NULL DEFAULT '{}',
  product_id    uuid REFERENCES catalog.product(id),
  qty           numeric(18,3) NOT NULL,
  unit_price    numeric(18,4) NOT NULL,
  tax_pct       numeric(5,2) NOT NULL DEFAULT 0,
  amount        numeric(18,2) NOT NULL,
  CONSTRAINT ck_invoice_line CHECK (qty > 0 AND unit_price >= 0)
);

CREATE TABLE finance.match_result (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_line_id   uuid NOT NULL REFERENCES finance.invoice_line(id),
  po_line_id        uuid REFERENCES procurement.purchase_order_line(id),
  qty_po            numeric(18,3),
  qty_grn_accepted  numeric(18,3),
  qty_invoiced      numeric(18,3) NOT NULL,
  price_po          numeric(18,4),
  price_invoiced    numeric(18,4) NOT NULL,
  variance_amount   numeric(18,2) NOT NULL DEFAULT 0,
  status            text NOT NULL,
  tolerance_applied jsonb,
  resolution        text,
  resolved_by       uuid REFERENCES identity.app_user(id),
  resolved_at       timestamptz,
  matched_at        timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ck_match_status CHECK (status IN ('MATCHED','QTY_MISMATCH','PRICE_MISMATCH','MISSING_GRN','MISSING_PO'))
);

CREATE TABLE finance.grn_verification (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  grn_id      uuid NOT NULL REFERENCES receiving.grn(id),
  status      text NOT NULL,
  remarks     text,
  verified_by uuid NOT NULL REFERENCES identity.app_user(id),
  verified_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ck_grn_verif CHECK (status IN ('VERIFIED','REJECTED'))
);

CREATE TABLE finance.payment_record (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id  uuid NOT NULL REFERENCES finance.invoice(id),
  amount      numeric(18,2) NOT NULL,
  paid_on     date NOT NULL,
  reference   text NOT NULL,
  mode        text,
  recorded_by uuid REFERENCES identity.app_user(id),
  created_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ck_payment_amount CHECK (amount > 0)
);

