CREATE INDEX ix_delivery_subject ON notify.notification_delivery (subject_type, subject_id);
CREATE INDEX ix_delivery_dedupe ON notify.notification_delivery (dedupe_key);
CREATE TABLE notify.notification_delivery_default PARTITION OF notify.notification_delivery DEFAULT;
CREATE TABLE notify.notification_delivery_2026_09 PARTITION OF notify.notification_delivery FOR VALUES FROM ('2026-09-01') TO ('2026-10-01');
CREATE TABLE notify.notification_delivery_2026_10 PARTITION OF notify.notification_delivery FOR VALUES FROM ('2026-10-01') TO ('2026-11-01');

-- Monotonic status progression; terminal states READ, FAILED, NOT_REGISTERED never regress (pattern retained from legacy delivery tracking; WhatsApp itself removed, DEC-001).
CREATE OR REPLACE FUNCTION notify.guard_delivery_status() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  rank_old int := CASE OLD.status WHEN 'QUEUED' THEN 0 WHEN 'SENDING' THEN 1 WHEN 'RETRY_SCHEDULED' THEN 1
                   WHEN 'SENT' THEN 2 WHEN 'DELIVERED' THEN 3 ELSE 9 END;
  rank_new int := CASE NEW.status WHEN 'QUEUED' THEN 0 WHEN 'SENDING' THEN 1 WHEN 'RETRY_SCHEDULED' THEN 1
                   WHEN 'SENT' THEN 2 WHEN 'DELIVERED' THEN 3 ELSE 9 END;
BEGIN
  IF OLD.status IN ('READ','FAILED','NOT_REGISTERED') AND NEW.status <> OLD.status THEN
    NEW.status := OLD.status;                 -- ignore regression silently (late webhooks)
  ELSIF rank_new < rank_old AND NOT (OLD.status = 'SENDING' AND NEW.status = 'RETRY_SCHEDULED')
                            AND NOT (OLD.status = 'RETRY_SCHEDULED' AND NEW.status = 'SENDING') THEN
    NEW.status := OLD.status;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER tg_delivery_status_guard BEFORE UPDATE OF status ON notify.notification_delivery
  FOR EACH ROW EXECUTE FUNCTION notify.guard_delivery_status();

