CREATE TABLE audit.audit_log (
  id                uuid NOT NULL DEFAULT gen_random_uuid(),
  occurred_at       timestamptz NOT NULL DEFAULT now(),
  organization_id   uuid NOT NULL,
  actor_id          uuid,
  actor_type        text NOT NULL,
  on_behalf_of_id   uuid,
  action            text NOT NULL,
  entity_type       text NOT NULL,
  entity_id         uuid,
  entity_number     text,
  before            jsonb,
  after             jsonb,
  diff              jsonb,
  request_id        text,
  correlation_id    text,
  trace_id          text,
  ip                inet,
  user_agent        text,
  channel           text,
  prev_hash         bytea,
  hash              bytea,
  PRIMARY KEY (id, occurred_at),
  CONSTRAINT ck_audit_actor_type CHECK (actor_type IN ('USER','SYSTEM','INTEGRATION'))
) PARTITION BY RANGE (occurred_at);
CREATE INDEX ix_audit_entity ON audit.audit_log (entity_type, entity_id, occurred_at);
CREATE INDEX ix_audit_actor ON audit.audit_log (actor_id, occurred_at);
CREATE INDEX ix_audit_request ON audit.audit_log (request_id);
CREATE TABLE audit.audit_log_default PARTITION OF audit.audit_log DEFAULT;
CREATE TABLE audit.audit_log_2026_09 PARTITION OF audit.audit_log FOR VALUES FROM ('2026-09-01') TO ('2026-10-01');
CREATE TABLE audit.audit_log_2026_10 PARTITION OF audit.audit_log FOR VALUES FROM ('2026-10-01') TO ('2026-11-01');
CREATE TRIGGER tg_audit_append_only BEFORE UPDATE OR DELETE ON audit.audit_log
  FOR EACH ROW EXECUTE FUNCTION public.forbid_mutation();

