) PARTITION BY RANGE (occurred_at);
CREATE INDEX ix_security_user ON audit.security_event (user_id, occurred_at);
CREATE TABLE audit.security_event_default PARTITION OF audit.security_event DEFAULT;

CREATE TABLE audit.login_event (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  occurred_at timestamptz NOT NULL DEFAULT now(),
  user_id     uuid,
  outcome     text NOT NULL,
  method      text NOT NULL,
  ip          inet,
  device      text,
  CONSTRAINT ck_login_outcome CHECK (outcome IN ('SUCCESS','FAILURE','LOCKED','MFA_REQUIRED','MFA_FAILED'))
);
CREATE INDEX ix_login_user ON audit.login_event (user_id, occurred_at DESC);

-- =============================================================================
-- EVENTS (transactional outbox / inbox / DLQ)
-- =============================================================================
CREATE TABLE events.outbox (
  id                uuid PRIMARY KEY,
  organization_id   uuid NOT NULL,
  event_type        text NOT NULL,
  event_version     integer NOT NULL DEFAULT 1,
  aggregate_type    text NOT NULL,
  aggregate_id      text NOT NULL,
  aggregate_version integer NOT NULL,
  payload           jsonb NOT NULL,
  metadata          jsonb NOT NULL,
  created_at        timestamptz NOT NULL DEFAULT now(),
  published_at      timestamptz,
  publish_attempts  integer NOT NULL DEFAULT 0,
  last_error        text
);
CREATE INDEX ix_outbox_unpublished ON events.outbox (created_at) WHERE published_at IS NULL;
CREATE INDEX ix_outbox_aggregate ON events.outbox (aggregate_type, aggregate_id, aggregate_version);

CREATE OR REPLACE FUNCTION events.notify_outbox() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  PERFORM pg_notify('outbox_new', NEW.id::text);
  RETURN NULL;
END $$;
CREATE TRIGGER tg_outbox_notify AFTER INSERT ON events.outbox
  FOR EACH ROW EXECUTE FUNCTION events.notify_outbox();

CREATE TABLE events.processed_event (
  consumer      text NOT NULL,
  event_id      uuid NOT NULL,
  processed_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (consumer, event_id)
);

CREATE TABLE events.consumer_position (
  consumer          text NOT NULL,
  aggregate_type    text NOT NULL,
  aggregate_id      text NOT NULL,
  last_version      integer NOT NULL,
  PRIMARY KEY (consumer, aggregate_type, aggregate_id)
);

CREATE TABLE events.dead_letter (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  consumer    text NOT NULL,
  event_id    uuid NOT NULL,
  event_type  text NOT NULL,
  payload     jsonb NOT NULL,
  error       text NOT NULL,
  attempts    integer NOT NULL,
  failed_at   timestamptz NOT NULL DEFAULT now(),
  replayed_at timestamptz,
  replayed_by uuid,
  CONSTRAINT uq_dead_letter UNIQUE (consumer, event_id)
);

-- =============================================================================
-- IO (imports, exports, idempotency)
-- =============================================================================
CREATE TABLE io.import_batch (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id   uuid NOT NULL REFERENCES org.organization(id),
  kind              text NOT NULL,
  file_document_id  uuid REFERENCES docs.document(id),
  file_name         text NOT NULL,
  file_sha256       char(64) NOT NULL,
  cycle_id          uuid REFERENCES recon.payment_cycle(id),
  status            text NOT NULL DEFAULT 'UPLOADED',
  preview_only      boolean NOT NULL DEFAULT true,
  force_reprocess   boolean NOT NULL DEFAULT false,
  total_rows        integer NOT NULL DEFAULT 0,
  processed_rows    integer NOT NULL DEFAULT 0,
  succeeded_rows    integer NOT NULL DEFAULT 0,
  failed_rows       integer NOT NULL DEFAULT 0,
  metrics           jsonb,
  options           jsonb,
  result_document_id uuid REFERENCES docs.document(id),
  uploaded_by       uuid REFERENCES identity.app_user(id),
  created_at        timestamptz NOT NULL DEFAULT now(),
  started_at        timestamptz,
  completed_at      timestamptz,
  CONSTRAINT ck_import_kind CHECK (kind IN ('PRODUCT_MAPPING','VENDOR_PRODUCT','MPP_MASTER','SAP_PO','SAP_SALES','RECON_SHEET','OPENING_STOCK','INDENT_BULK','STOCK_SALE','STOCK_FILLED','STOCK_CORRECTED','SAP_ORDER_DEMAND','LEGACY_MIGRATION')),
  CONSTRAINT ck_import_status CHECK (status IN ('UPLOADED','VALIDATING','VALIDATION_FAILED','PREVIEW_READY','PROCESSING','PROCESSED','PROCESSED_WITH_EXCEPTIONS','PARTIAL','FAILED','DISCARDED','PUBLISHED','SUPERSEDED')),
  CONSTRAINT ck_import_counts CHECK (succeeded_rows + failed_rows <= processed_rows AND processed_rows <= total_rows)
);
CREATE UNIQUE INDEX uq_import_file ON io.import_batch (organization_id, kind, coalesce(cycle_id, '00000000-0000-0000-0000-000000000000'::uuid), file_sha256)
  WHERE NOT force_reprocess AND status NOT IN ('DISCARDED','FAILED','VALIDATION_FAILED');

CREATE TABLE io.import_error (
  id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  batch_id    uuid NOT NULL REFERENCES io.import_batch(id) ON DELETE CASCADE,
  row_index   integer NOT NULL,
  field       text,
  value       text,
  rule        text NOT NULL,
  message     text NOT NULL,
  suggestion  text,
  is_critical boolean NOT NULL DEFAULT true
);
CREATE INDEX ix_import_error_batch ON io.import_error (batch_id, row_index);

CREATE TABLE io.import_row_audit (
  id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  batch_id    uuid NOT NULL REFERENCES io.import_batch(id) ON DELETE CASCADE,
  row_index   integer NOT NULL,
  action      text NOT NULL,
  entity_type text NOT NULL,
  entity_id   uuid,
  changes     jsonb,
  CONSTRAINT ck_row_audit_action CHECK (action IN ('CREATE','UPDATE','MERGE','SKIP','REJECT','DEACTIVATE'))
);

ALTER TABLE procurement.sap_po_line
  ADD CONSTRAINT fk_sap_po_import FOREIGN KEY (import_batch_id) REFERENCES io.import_batch(id);
ALTER TABLE recon.reconciliation_sheet
  ADD CONSTRAINT fk_recon_sheet_import FOREIGN KEY (import_batch_id) REFERENCES io.import_batch(id);

CREATE TABLE io.export_job (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  report_key    text NOT NULL,
  format        text NOT NULL,
  filters       jsonb,
  columns       text[],
  status        text NOT NULL DEFAULT 'QUEUED',
  row_count     integer,
  document_id   uuid REFERENCES docs.document(id),
  requested_by  uuid NOT NULL REFERENCES identity.app_user(id),
  requested_at  timestamptz NOT NULL DEFAULT now(),
  completed_at  timestamptz,
  expires_at    timestamptz,
  CONSTRAINT ck_export_format CHECK (format IN ('CSV','XLSX','PDF')),
  CONSTRAINT ck_export_status CHECK (status IN ('QUEUED','RUNNING','COMPLETED','FAILED','EXPIRED'))
);

CREATE TABLE io.idempotency_record (
  organization_id uuid NOT NULL,
  user_id         uuid NOT NULL,
  idem_key        uuid NOT NULL,
  operation       text NOT NULL,
  request_hash    bytea NOT NULL,
  status          text NOT NULL DEFAULT 'IN_PROGRESS',
  response        jsonb,
  http_status     integer,
  created_at      timestamptz NOT NULL DEFAULT now(),
  expires_at      timestamptz NOT NULL DEFAULT now() + interval '24 hours',
  PRIMARY KEY (organization_id, user_id, idem_key),
  CONSTRAINT ck_idem_status CHECK (status IN ('IN_PROGRESS','COMPLETED','FAILED'))
);
CREATE INDEX ix_idem_expiry ON io.idempotency_record (expires_at);

CREATE TABLE io.saved_filter (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     uuid NOT NULL REFERENCES identity.app_user(id) ON DELETE CASCADE,
  list_key    text NOT NULL,
  name        text NOT NULL,
  filters     jsonb NOT NULL,
  columns     text[],
  is_default  boolean NOT NULL DEFAULT false,
  CONSTRAINT uq_saved_filter UNIQUE (user_id, list_key, name)
);

-- Deferred FKs to documents from identity/procurement
ALTER TABLE identity.app_user
  ADD CONSTRAINT fk_user_signature FOREIGN KEY (signature_document_id) REFERENCES docs.document(id),
  ADD CONSTRAINT fk_user_seal FOREIGN KEY (seal_document_id) REFERENCES docs.document(id);
ALTER TABLE procurement.quotation
  ADD CONSTRAINT fk_quotation_document FOREIGN KEY (document_id) REFERENCES docs.document(id);
ALTER TABLE indent.indent
  ADD CONSTRAINT fk_indent_workflow FOREIGN KEY (workflow_instance_id) REFERENCES workflow.workflow_instance(id);


-- =============================================================================
-- REPORTING: product stock report (RPT-006/007) and sales to other parties (MPP-013)
-- =============================================================================
CREATE TABLE reporting.report_product (
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  product_id      uuid NOT NULL REFERENCES catalog.product(id),
  display_name    text,
  position        integer NOT NULL,
  is_base         boolean NOT NULL DEFAULT false,
  scope_location_ids uuid[] NOT NULL DEFAULT '{}',   -- empty = all locations
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (organization_id, product_id),
  CONSTRAINT ck_report_product_position CHECK (position >= 0)
);
COMMENT ON TABLE reporting.report_product IS 'Sale & Stock Report product list: 35 base products (is_base, seeded from live stock_report.py, OQ-053) + admin-added';

CREATE TABLE reporting.stock_statement (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id       uuid NOT NULL REFERENCES org.organization(id),
  cycle_id              uuid NOT NULL REFERENCES recon.payment_cycle(id),
  status                text NOT NULL DEFAULT 'OPEN',
  is_manual_override    boolean NOT NULL DEFAULT false,
  override_uploaded_at  timestamptz,
  generated_at          timestamptz,
  generated_by          uuid REFERENCES identity.app_user(id),
  sale_uploaded_at      timestamptz,
  sale_document_id      uuid REFERENCES docs.document(id),
  sale_file_name        text,
  sale_rows_total       integer NOT NULL DEFAULT 0,
  sale_rows_matched     integer NOT NULL DEFAULT 0,
  sale_rows_unmatched   integer NOT NULL DEFAULT 0,
  finalized_at          timestamptz,
  finalized_by          uuid REFERENCES identity.app_user(id),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  version               integer NOT NULL DEFAULT 1,
  CONSTRAINT uq_stock_statement_cycle UNIQUE (cycle_id),
  CONSTRAINT ck_stock_statement_status CHECK (status IN ('OPEN','FINALIZED')),
  CONSTRAINT ck_stock_statement_final CHECK (status <> 'FINALIZED' OR finalized_at IS NOT NULL),
  CONSTRAINT ck_stock_statement_rows CHECK (sale_rows_matched + sale_rows_unmatched = sale_rows_total)
);

CREATE TABLE reporting.stock_statement_entry (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  statement_id          uuid NOT NULL REFERENCES reporting.stock_statement(id),
  location_id           uuid NOT NULL REFERENCES org.location(id),
  product_id            uuid NOT NULL REFERENCES catalog.product(id),
  opening_balance       integer NOT NULL DEFAULT 0,
  received              integer NOT NULL DEFAULT 0,   -- Received NDS / Other Co.
  received_mcc          integer NOT NULL DEFAULT 0,   -- Received MCC/BMC
  stock_transfer        integer NOT NULL DEFAULT 0,   -- stock sent out, stored <= 0
  mpp_sale              integer NOT NULL DEFAULT 0,   -- from SAP sale upload
  transporter_deduction integer NOT NULL DEFAULT 0,
  damage                integer NOT NULL DEFAULT 0,
  expire                integer NOT NULL DEFAULT 0,
  closing_balance       integer GENERATED ALWAYS AS (
                          opening_balance + received + received_mcc - abs(stock_transfer)
                          - mpp_sale - transporter_deduction - damage - expire) STORED,
  remark                varchar(255) NOT NULL DEFAULT '',
  received_synced       integer,                      -- per-column baselines: an edited flow column is
  received_mcc_synced   integer,                      -- kept until new inventory movements arrive
  stock_transfer_synced integer,
  updated_at            timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_stock_statement_entry UNIQUE (statement_id, location_id, product_id),
  CONSTRAINT ck_sse_transfer CHECK (stock_transfer <= 0),
  CONSTRAINT ck_sse_manual_nonneg CHECK (transporter_deduction >= 0 AND damage >= 0 AND expire >= 0)
);
CREATE INDEX ix_sse_location ON reporting.stock_statement_entry (location_id, statement_id);

CREATE TABLE reporting.statement_location_state (
  statement_id      uuid NOT NULL REFERENCES reporting.stock_statement(id),
  location_id       uuid NOT NULL REFERENCES org.location(id),
  transporter_open  boolean NOT NULL DEFAULT false,
  damage_open       boolean NOT NULL DEFAULT false,
  expire_open       boolean NOT NULL DEFAULT false,
  updated_by        uuid REFERENCES identity.app_user(id),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (statement_id, location_id)
);

CREATE TABLE reporting.mpp_sale_row (
  id                    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  statement_id          uuid NOT NULL REFERENCES reporting.stock_statement(id),
  sap_plant             text,
  sap_mcc_name          text,
  sap_mpp_code          text,
  sap_mpp_name          text,
  sap_material_code     text,
  sap_material_desc     text,
  quantity              integer NOT NULL,
  matched               boolean NOT NULL DEFAULT false,
  location_id           uuid REFERENCES org.location(id),
  product_id            uuid REFERENCES catalog.product(id),
  CONSTRAINT ck_msr_matched CHECK (NOT matched OR (location_id IS NOT NULL AND product_id IS NOT NULL))
);
CREATE INDEX ix_msr_statement ON reporting.mpp_sale_row (statement_id, matched);

CREATE TABLE reporting.sale_product_alias (
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  alias           text NOT NULL,
  product_id      uuid NOT NULL REFERENCES catalog.product(id),
  PRIMARY KEY (organization_id, alias)
);

CREATE TABLE reporting.stock_statement_cell_audit (
  id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  entry_id      uuid NOT NULL REFERENCES reporting.stock_statement_entry(id),
  column_key    text NOT NULL,
  old_value     text,
  new_value     text,
  reason        text,
  source        text NOT NULL,
  changed_by    uuid REFERENCES identity.app_user(id),
  changed_at    timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ck_cell_audit_source CHECK (source IN ('INLINE_ADMIN','INLINE_LOCATION','FILLED_UPLOAD','CORRECTED_UPLOAD','SALE_UPLOAD','REFRESH'))
);
CREATE TRIGGER tg_cell_audit_append_only BEFORE UPDATE OR DELETE ON reporting.stock_statement_cell_audit
  FOR EACH ROW EXECUTE FUNCTION public.forbid_mutation();

CREATE TABLE org.region_member (
  region_id   uuid NOT NULL REFERENCES org.region(id),
  location_id uuid NOT NULL REFERENCES org.location(id),
  PRIMARY KEY (region_id, location_id)
);
ALTER TABLE org.region ADD COLUMN is_active boolean NOT NULL DEFAULT true;   -- ClusterZone

CREATE TABLE mpp.other_sale (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES org.organization(id),
  sale_number     text NOT NULL,
  location_id     uuid NOT NULL REFERENCES org.location(id),
  warehouse_id    uuid NOT NULL REFERENCES org.warehouse(id),
  invoice_number  text NOT NULL,
  party_name      text NOT NULL,
  party_address   text,
  party_gstin     text,
  invoice_document_id uuid REFERENCES docs.document(id),
  status          text NOT NULL DEFAULT 'ISSUED',
  client_ref      uuid NOT NULL,
  created_by      uuid NOT NULL REFERENCES identity.app_user(id),
  created_at      timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_other_sale_number UNIQUE (organization_id, sale_number),
  CONSTRAINT uq_other_sale_invoice UNIQUE (organization_id, invoice_number),
  CONSTRAINT uq_other_sale_client UNIQUE (organization_id, created_by, client_ref),
  CONSTRAINT ck_other_sale_status CHECK (status IN ('ISSUED','CANCELLED'))
);

CREATE TABLE mpp.other_sale_line (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  other_sale_id uuid NOT NULL REFERENCES mpp.other_sale(id),
  product_id    uuid NOT NULL REFERENCES catalog.product(id),
  qty_base      numeric(18,3) NOT NULL,
  unit_price    numeric(18,4) NOT NULL,
  CONSTRAINT ck_other_sale_line CHECK (qty_base > 0 AND unit_price >= 0)
);

-- =============================================================================
-- ROW-LEVEL SECURITY (defence in depth; app sets: SET LOCAL app.org_id = '<uuid>')
-- =============================================================================
DO $$
DECLARE t record;
BEGIN
  FOR t IN
    SELECT c.table_schema, c.table_name
    FROM information_schema.columns c
    JOIN information_schema.tables tb ON tb.table_schema = c.table_schema AND tb.table_name = c.table_name
    WHERE c.column_name = 'organization_id'
      AND tb.table_type = 'BASE TABLE'
      AND c.table_schema IN ('org','identity','config','catalog','indent','workflow','procurement','receiving','logistics','inventory','mpp','recon','finance','docs','notify','io','reporting')
      AND c.table_name NOT LIKE '%\_default' AND c.table_name !~ '_[0-9]{4}_[0-9]{2}$'
  LOOP
    EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', t.table_schema, t.table_name);
    EXECUTE format($p$CREATE POLICY p_org_isolation ON %I.%I
                     USING (organization_id = nullif(current_setting('app.org_id', true), '')::uuid)
                     WITH CHECK (organization_id = nullif(current_setting('app.org_id', true), '')::uuid)$p$,
                   t.table_schema, t.table_name);
  END LOOP;
END $$;

